'use client';
import { useId, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import { spring, springToLinear, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import { FPS, ICONS, type IconId } from './icons';
import type { LottieAnimation } from './lottie-kit';
import { LottieIcon, type LottieIconHandle } from './LottieIcon';
import { Timeline, type TimelineApi, type TimelineLane } from './Timeline';
import styles from './styles.module.css';

export { LottieIcon } from './LottieIcon';
export type { LottieIconHandle, LottieIconProps } from './LottieIcon';
export type { LottieSegments } from './segments';
export { ICONS } from './icons';

type Params = { size: number; weight: number; tint: string; speed: number; hover: boolean };

/** Accessible names: constant, the state lives in aria-pressed / aria-expanded. */
const LABEL: Record<IconId, string> = { menu: 'Queue', play: 'Play', heart: 'Like', bookmark: 'Save', bell: 'New-episode alerts', theme: 'Night mode' };
const LANE: Record<IconId, string> = { menu: 'Queue', play: 'Play', heart: 'Like', bookmark: 'Save', bell: 'Alerts', theme: 'Night' };
const ORDER: readonly IconId[] = ['menu', 'play', 'heart', 'bookmark', 'bell', 'theme'];
const OFF: Record<IconId, boolean> = { menu: false, play: false, heart: false, bookmark: false, bell: false, theme: false };

/** Fictional show, sample data. */
const LIKES = 214;
const QUEUE = [
  { n: 13, title: 'The lighthouse keeper’s ledger', min: 41 },
  { n: 14, title: 'Fog signals, decoded', min: 33 },
  { n: 15, title: 'Night shift on the slipway', min: 47 },
];

export default function LottieMicroInteractions({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const [on, setOn] = useState(OFF);
  const [likeTicks, setLikeTicks] = useState(0); // the count only rolls after a real like/unlike, never on load
  const weight = params.weight;
  const data = useMemo(
    () => Object.fromEntries(ORDER.map((id) => [id, ICONS[id].build(weight)])) as Record<IconId, LottieAnimation>,
    [weight],
  );
  const handles = useRef<Partial<Record<IconId, LottieIconHandle | null>>>({});
  const timeline = useRef<TimelineApi | null>(null);
  const press = useMemo(() => springToLinear(spring.press), []);
  const settle = useMemo(() => springToLinear(spring.settle), []);
  const tint = ['duotone', 'accent', 'ink'].includes(params.tint) ? params.tint : 'duotone';
  const size = Math.round(params.size);

  const icon = (id: IconId, opts: { size: number; className: string; children?: ReactNode; disclosure?: boolean }) => (
    <LottieIcon
      animationData={data[id]}
      segments={ICONS[id].segments}
      grid={24}
      label={LABEL[id]}
      pressed={on[id]}
      onToggle={(v) => {
        setOn((s) => ({ ...s, [id]: v }));
        if (id === 'heart') setLikeTicks((n) => n + 1);
      }}
      kind={opts.disclosure ? 'disclosure' : 'toggle'}
      controls={opts.disclosure ? `${uid}queue` : undefined}
      size={opts.size}
      speed={params.speed}
      hover={params.hover}
      className={opts.className}
      onFrame={(f) => timeline.current?.update(id, f)}
      handle={(h) => { handles.current[id] = h; }}
    >
      {opts.children}
    </LottieIcon>
  );

  const lanes: TimelineLane[] = ORDER.map((id) => ({
    id,
    name: LANE[id],
    segments: ICONS[id].segments,
    rest: on[id] ? ICONS[id].segments.on[1] : ICONS[id].segments.on[0],
    scrub: (f) => handles.current[id]?.scrub(f),
    release: () => handles.current[id]?.release(),
  }));

  return (
    <div
      className={styles.root}
      data-reduced={reduced || undefined}
      style={{
        '--press-ease': press.easing, '--press-duration': `${press.duration}ms`,
        '--settle-ease': settle.easing, '--settle-duration': `${settle.duration}ms`,
      } as CSSProperties}
    >
      <div className={styles.layout}>
        <div className={styles.column}>
          <section
            className={styles.card}
            data-tint={tint}
            data-night={on.theme || undefined}
            data-playing={on.play || undefined}
            aria-label="Sample podcast player"
            onKeyDown={(e) => { if (e.key === 'Escape' && on.menu) setOn((s) => ({ ...s, menu: false })); }}
          >
            <header className={styles.bar}>
              {icon('menu', { size, className: styles.iconButton, disclosure: true })}
              <p className={styles.brand}>
                <span className={styles.show}>Tidewater FM</span>
                <span className={styles.sample}>Fictional show · sample UI</span>
              </p>
              <div className={styles.barEnd}>
                {icon('bell', { size, className: styles.iconButton })}
                {icon('theme', { size, className: styles.iconButton })}
              </div>
            </header>

            <div id={`${uid}queue`} className={styles.queue} data-open={on.menu || undefined}>
              <p className={styles.queueTitle}>Up next · sample queue</p>
              <ol className={styles.queueList}>
                {QUEUE.map((q) => (
                  <li key={q.n}><span className={styles.queueNo}>{q.n}</span><span className={styles.queueName}>{q.title}</span><span className={styles.queueMin}>{q.min} min</span></li>
                ))}
              </ol>
            </div>

            <div className={styles.now}>
              <div className={styles.cover} aria-hidden="true">
                <span className={styles.sun} />
                <span className={styles.moon} />
                <svg className={styles.waves} viewBox="0 0 80 32" preserveAspectRatio="none" focusable="false">
                  <path d="M0 10 C 10 4, 20 4, 30 10 S 50 16, 60 10 S 75 4, 80 8" />
                  <path d="M0 19 C 12 13, 22 13, 34 19 S 56 25, 66 19 S 76 14, 80 16" />
                  <path d="M0 28 C 10 23, 22 23, 32 28 S 54 33, 64 28 S 76 24, 80 26" />
                </svg>
              </div>
              <div className={styles.meta}>
                <p className={styles.kicker}>Episode 12 · 38 min</p>
                <h3 className={styles.title}>Salt, static and the night ferry</h3>
                <p className={styles.byline}>Ines Varga &amp; Tomasz Ode</p>
              </div>
            </div>

            <div className={styles.progress}>
              <div className={styles.track} aria-hidden="true"><span className={styles.fill} /><span className={styles.knob} /></div>
              <p className={styles.times}>
                <span className={styles.status}>
                  <span className={styles.eq} aria-hidden="true"><i /><i /><i /></span>
                  {on.play ? 'Playing' : 'Paused'}
                </span>
                <span>12:04 / 38:00</span>
              </p>
            </div>

            <div className={styles.controls}>
              <div className={styles.side}>
                {icon('heart', { size: Math.round(size * 1.08), className: styles.pill, children: <span className={styles.caption}>Like</span> })}
                <span className={styles.count}>
                  <span key={likeTicks} className={styles.countRoll} data-dir={likeTicks ? (on.heart ? 'up' : 'down') : undefined}>{LIKES + (on.heart ? 1 : 0)}</span>
                  <span className={styles.srOnly}> likes (sample)</span>
                </span>
              </div>
              {icon('play', { size: Math.round(size * 1.9), className: styles.primary })}
              <div className={`${styles.side} ${styles.sideEnd}`}>
                {icon('bookmark', { size: Math.round(size * 1.08), className: styles.pill, children: <span className={styles.caption}>Save</span> })}
              </div>
            </div>
          </section>
          <p className={styles.hint}>Hover or focus previews the wind&#8209;up · a click commits from that frame · click again mid&#8209;way to reverse</p>
        </div>

        <Timeline lanes={lanes} api={timeline} fps={FPS} />
      </div>
    </div>
  );
}

/**
 * Six original interactive icons, authored with ./lottie-kit on a 24-unit grid (8 units of bleed around it for
 * overshoot and bursts). Every transition starts with a wind-up that hover/focus previews, commits with overshoot,
 * and settles with follow-through; timings differ per icon so the set never moves in lockstep.
 *
 * Frame numbers are at 60 fps. The wind-up length is the `fast` motion token (hover, small state changes).
 */
import { duration } from '../../motion';
import {
  arc, circle, compose, draw, ellipse, ellipseAt, group, line, oscillation, polar, polyline, roundedPolygon, track,
  vertexAngles, type Ease, type LottieAnimation, type Path, type SceneNode, type StrokePaint, type Vec2,
} from './lottie-kit';
import type { LottieSegments } from './segments';

export const FPS = 60;
const fr = (ms: number): number => Math.round((ms / 1000) * FPS);
/** Hover/focus preview: the wind-up at the start of each transition. */
const WIND = fr(duration.fast);

export type IconId = 'menu' | 'play' | 'bookmark' | 'bell' | 'heart' | 'theme';

export interface IconDesign {
  id: IconId;
  segments: LottieSegments;
  /** Build the Lottie data for a stroke weight in grid units. */
  build: (weight: number) => LottieAnimation;
}

const lerp2 = (a: Vec2, b: Vec2, t: number): Vec2 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
type Keys = readonly (readonly [number, number, Ease])[];
/** A follower: the same keys `by` frames later and `gain` times larger, landing on `end` (clapper behind the bell). */
const lagged = (keys: Keys, by: number, gain: number, end: number): [number, number, Ease][] =>
  keys.map(([t, v, e], n) => [n === keys.length - 1 ? end : t + by, v * gain, e]);

/* ── Menu ⇄ close ──────────────────────────────────────────────────────────────────────────────────────────────
   The outer bars breathe apart and the middle bar draws back (wind-up), then the outer bars converge and cross on an
   overshoot while the middle one is swallowed; the cross lands with a small squash. Reversible as it stands. */
function menu(w: number): LottieAnimation {
  const W = WIND, MEET = 16, END = 32;
  const stroke: StrokePaint = { tone: 'ink', width: w };
  // The cross lands on a spring: past 45° to 53°, back to 43°, and settles.
  const land = (sign: number): Keys => [[20, 53 * sign, 'emphasized'], [24, 43 * sign, 'swing'], [27.5, 45.6 * sign, 'swing'], [31, 45 * sign, 'swing']];
  const bar = (name: string, y: number, spread: number, sign: number): SceneNode => draw(name, {
    paths: [line([-8, 0], [8, 0])],
    stroke,
    transform: {
      position: track<Vec2>([12, y]).to(W, [12, y + spread], 'standard').to(MEET, [12, 12], 'inOut'),
      rotation: track(0).hold(MEET - 2).keysTo(land(sign)),
    },
  });
  const middle = draw('middle', {
    paths: [line([0, 0], [16, 0])],
    stroke: { ...stroke, opacity: track(1).hold(12).to(15, 0, 'linear') },
    transform: { position: [4, 12], scale: track<Vec2>([1, 1]).to(W, [0.55, 1], 'standard').to(15, [0, 1], 'exit') },
  });
  const cross = group('menu', [middle, bar('bottom', 18, 1.2, -1), bar('top', 6, -1.2, 1)], {
    pivot: [12, 12],
    scale: track(1).hold(MEET - 1).to(MEET + 1, 0.9, 'exit').to(MEET + 6, 1.04, 'swing').to(MEET + 12, 1, 'swing'),
  });
  return compose({ name: 'Menu', frames: END, scene: [cross], markers: { on: [0, END] } });
}

/* ── Play ⇄ pause ──────────────────────────────────────────────────────────────────────────────────────────────
   The disc presses in while the triangle compresses against its back edge, then the two halves of the triangle
   spring apart into bars (the right half a beat later), stretch tall and settle. */
function play(w: number): LottieAnimation {
  const W = 8, END = 30;
  const left = track(polyline([[10, 8], [13.2, 10], [13.2, 14], [10, 16]], true))
    .hold(W).to(W + 9, polyline([[8.8, 8.2], [9.8, 8.2], [9.8, 15.8], [8.8, 15.8]], true), 'inOut');
  const right = track(polyline([[13.2, 10], [16.4, 12], [16.4, 12], [13.2, 14]], true))
    .hold(W + 1).to(W + 10, polyline([[14.2, 8.2], [15.2, 8.2], [15.2, 15.8], [14.2, 15.8]], true), 'inOut');
  const paint = { fill: { tone: 'on' as const }, stroke: { tone: 'on' as const, width: w } }; // round joins round the corners
  const disc = draw('disc', {
    paths: [circle([12, 12], 11)],
    fill: { tone: 'solid' },
    transform: { pivot: [12, 12], scale: track(1).to(W, 0.94, 'standard').to(W + 8, 1.05, 'emphasized').to(W + 15, 0.99, 'swing').to(END, 1, 'swing') },
  });
  const glyph = group('glyph', [
    group('stretch', [draw('left', { paths: [left], ...paint }), draw('right', { paths: [right], ...paint })], {
      pivot: [12, 12],
      scale: track<Vec2>([1, 1]).hold(W + 4).to(W + 10, [1.04, 1.14], 'emphasized').to(W + 16, [1, 0.95], 'swing').to(END, [1, 1], 'swing'),
    }),
  ], {
    pivot: [10, 12],
    scale: track<Vec2>([1, 1]).to(W, [0.86, 1.05], 'standard').to(W + 6, [1, 1], 'emphasized'),
    rotation: track(0).to(W, -7, 'standard').to(W + 9, 2, 'emphasized').to(W + 15, 0, 'swing'),
  });
  return compose({ name: 'Play / pause', frames: END, scene: [disc, glyph], markers: { on: [0, END] } });
}

/* ── Bookmark ──────────────────────────────────────────────────────────────────────────────────────────────────
   A drop of ink beads above the ribbon (wind-up), falls stretching, splats on the top edge and floods the ribbon;
   the ribbon, hanging from its top edge, stretches under the weight and bounces back. Unsaving lifts the ribbon and
   rolls the ink back up into the top edge. */
function bookmark(w: number): LottieAnimation {
  const W = WIND, HIT = 16, SPLAT = 18, FULL = 27, END = 42, OFF_W = END + 6, OFF_END = 58;
  const ribbon = roundedPolygon([[6.5, 3.5], [17.5, 3.5], [17.5, 20.5], [12, 16.4], [6.5, 20.5]], [2.2, 2.2, 0.6, 0.6, 0.6]);
  const angles = vertexAngles(ribbon, [12, 11]);
  const blob = (c: Vec2, rx: number, ry: number): Path => ellipseAt(c, rx, ry, angles);
  // A drop: the blob with its two top vertices (the ribbon's top edge) drawn up into a point.
  const tear = (c: Vec2, rx: number, ry: number, tip: number): Path => {
    const b = blob(c, rx, ry);
    const top = c[1] - ry - tip;
    return {
      ...b,
      v: b.v.map((p, n) => (n === 1 ? [c[0] - 0.04, top] : n === 2 ? [c[0] + 0.04, top] : p)),
      i: b.i.map((t, n) => (n === 1 ? [-rx * 0.42, ry * 0.7] : n === 2 ? [0, 0] : t)),
      o: b.o.map((t, n) => (n === 1 ? [0, 0] : n === 2 ? [rx * 0.42, ry * 0.7] : t)),
    };
  };
  const inkShape = track(blob([12, -0.8], 0.05, 0.05))
    .to(5, blob([12, -0.8], 1.65, 1.35), 'emphasized') // beads, a little wide (surface tension)
    .to(W, tear([12, -0.8], 1.45, 1.5, 1.4), 'swing') // hangs as a drop
    .to(HIT, tear([12, 8], 1.1, 2.1, 1.2), 'exit') //     falls, stretching as it speeds up
    .to(SPLAT, blob([12, 8.6], 3.5, 1.45), 'enter') //    splats on the top edge
    .to(FULL, ribbon, 'emphasized'); //                    floods the ribbon
  const ink = draw('ink', {
    paths: [inkShape],
    fill: { tone: 'tint' },
    stroke: { tone: 'tint', width: w },
    transform: {
      pivot: [12, 3.5],
      scale: track(1).hold(OFF_W).to(OFF_END - 2, 0, 'exit'),
      opacity: track(0).to(3, 1, 'linear').hold(OFF_END - 6).to(OFF_END - 2, 0, 'linear'),
    },
  });
  const outline = draw('outline', {
    paths: [ribbon],
    stroke: { tone: 'ink', width: w, opacity: track(1).hold(FULL).to(FULL + 3, 0, 'linear').hold(END).to(END + 2, 1, 'linear') },
  });
  // The ribbon hangs from its top edge: the impact stretches it down, it recoils, then settles.
  const hanging = group('ribbon', [outline, ink], {
    pivot: [12, 3.5],
    scale: track<Vec2>([1, 1]).hold(SPLAT).keysTo([
      [SPLAT + 5, [0.96, 1.09], 'enter'], [SPLAT + 12, [1.02, 0.965], 'swing'], [SPLAT + 18, [0.995, 1.012], 'swing'], [END, [1, 1], 'swing'],
      [OFF_W, [1.01, 0.95], 'standard'], [OFF_END - 4, [0.99, 1.02], 'emphasized'], [OFF_END, [1, 1], 'swing'],
    ]),
  });
  return compose({ name: 'Bookmark', frames: OFF_END, scene: [hanging], markers: { on: [0, END], off: [END, OFF_END] } });
}

/* ── Bell ──────────────────────────────────────────────────────────────────────────────────────────────────────
   Alerts off shows a struck-through bell. Turning alerts on pulls the slash out, tilts the bell back and lets it go:
   a damped ring about the hanger, with the clapper lagging two frames behind at a wider swing, and sound waves
   thrown out on the first swings. Turning off muffles the bell with a short dead swing and strikes the slash back. */
function bell(w: number): LottieAnimation {
  const W = 8, END = 42, OFF_W = END + 6, OFF_END = 62;
  const PIVOT: Vec2 = [12, 3.2];
  const ring = oscillation(0, 18, { start: W, halfPeriod: 5.5, decay: 0.58, swings: 5 });
  const muffle: Keys = [[OFF_W, 4, 'standard'], [OFF_W + 5, -3, 'swing'], [OFF_W + 9, 1.2, 'swing'], [OFF_W + 12, 0, 'swing']];
  const body = draw('bell', {
    paths: [{ v: [[12, 4.4], [17.4, 10.2], [19.2, 16.6], [4.8, 16.6], [6.6, 10.2]], i: [[-3, 0], [0, -3.2], [-1.4, -1.2], [0, 0], [0, 3.6]], o: [[3, 0], [0, 3.6], [0, 0], [1.4, -1.2], [0, -3.2]], c: true }],
    stroke: { tone: 'ink', width: w },
    transform: { pivot: PIVOT, rotation: track(0).to(W, -9, 'standard').keysTo(ring).hold(END).keysTo(muffle) },
  });
  const clapper = draw('clapper', {
    paths: [arc([12, 17.3], 2.3, 115, 245, 2)],
    stroke: { tone: 'ink', width: w },
    transform: { pivot: PIVOT, rotation: track(0).to(W + 1, -5, 'standard').keysTo(lagged(ring, 2, 1.3, END)).keysTo(lagged(muffle, 1.5, 1.4, OFF_END - 1)) },
  });
  const wave = (name: string, from: number, to: number, delay: number): SceneNode => draw(name, {
    paths: [arc([12, 11], 9.6, from, to, 1)],
    stroke: { tone: 'tint', width: w, opacity: track(0).hold(W + delay).to(W + delay + 3, 1, 'linear').hold(OFF_W + 2).to(OFF_W + 6, 0, 'linear') },
    transform: {
      pivot: [12, 11],
      scale: track(0.6).hold(W + delay).to(W + delay + 7, 1.14, 'emphasized').to(W + delay + 16, 1, 'swing').hold(END).to(OFF_W, 0.88, 'standard').to(OFF_W + 6, 0.5, 'exit'),
    },
  });
  const S: Vec2 = [3.8, 3.8], E: Vec2 = [20.2, 20.2];
  const slashShape = track(line(S, E)).to(W, line(lerp2(S, E, 0.12), E), 'standard').to(W + 9, line(E, E), 'exit')
    .to(OFF_W, line(S, S), 'hold').to(OFF_W + 9, line(S, E), 'emphasized');
  const slashOpacity = track(1).hold(W + 7).to(W + 9, 0, 'linear').to(OFF_W, 1, 'hold');
  // The knock-out is the slash drawn wider in the background colour: it opens a gap where the slash crosses the bell.
  const knock = draw('knock', { paths: [slashShape], stroke: { tone: 'knock', width: w + 2.4, opacity: slashOpacity } });
  const slash = draw('slash', { paths: [slashShape], stroke: { tone: 'ink', width: w, opacity: slashOpacity } });
  return compose({
    name: 'Bell', frames: OFF_END,
    scene: [body, clapper, wave('wave right', 58, 92, 3), wave('wave left', 268, 302, 9), knock, slash],
    markers: { on: [0, END], off: [END, OFF_END] },
  });
}

/* ── Heart ─────────────────────────────────────────────────────────────────────────────────────────────────────
   The heart crouches on its tip (wind-up), springs up stretched while the fill pops out from its centre, then lands
   with a squash; a ring and two orbits of particles burst out on curved paths. Un-liking is quieter: a small squash
   and the fill sinks back into the centre. */
function heartPath(R = 4.3, half = 4.1, cy = 9, tipY = 19.8): Path {
  const rise = Math.sqrt(R * R - half * half);
  const dipY = cy - rise;
  const lobe = Math.asin(half / R); // angle of the dip on each lobe circle, from 12 o'clock
  const hD = (4 / 3) * Math.tan(lobe / 4) * R; // handle for the arc from the dip to the lobe top
  const hQ = (4 / 3) * Math.tan(Math.PI / 8) * R; // quarter circle
  const cx = Math.cos(lobe), sy = Math.sin(lobe);
  const k1 = R * 0.86, k2: Vec2 = [R * 0.84, R * 0.78];
  return {
    v: [[12, dipY], [12 + half, cy - R], [12 + half + R, cy], [12, tipY], [12 - half - R, cy], [12 - half, cy - R]],
    i: [[-cx * hD, -sy * hD], [-hD, 0], [0, -hQ], [k2[0], -k2[1]], [0, k1], [-hQ, 0]],
    o: [[cx * hD, -sy * hD], [hQ, 0], [0, k1], [-k2[0], -k2[1]], [0, -hQ], [hD, 0]],
    c: true,
  };
}

function heart(w: number): LottieAnimation {
  const W = 9, END = 34, OFF_W = END + 6, OFF_END = 50;
  const shape = heartPath();
  const C: Vec2 = [12, 12.5];
  const outline = draw('outline', {
    paths: [shape],
    stroke: { tone: 'ink', width: w, opacity: track(1).hold(22).to(26, 0, 'linear').hold(END).to(END + 2, 1, 'linear') },
  });
  const fillHeart = draw('fill', {
    paths: [shape],
    fill: { tone: 'tint' },
    stroke: { tone: 'tint', width: w },
    transform: {
      pivot: [12, 12],
      scale: track(0).hold(W + 1).to(22, 1, 'overshoot').hold(OFF_W).to(OFF_END - 2, 0, 'exit'),
      opacity: track(0).hold(W + 1).to(W + 3, 1, 'linear').hold(OFF_END - 6).to(OFF_END - 2, 0, 'linear'),
    },
  });
  const body = group('heart', [outline, fillHeart], {
    pivot: [12, 19.8],
    position: track<Vec2>([12, 19.8]).hold(W).to(14, [12, 18.6], 'enter').to(20, [12, 19.8], 'standard'),
    scale: track<Vec2>([1, 1]).keysTo([
      [W, [1.08, 0.88], 'standard'], [14, [0.88, 1.14], 'exit'], [19, [1.1, 0.92], 'enter'], [25, [0.97, 1.03], 'swing'], [31, [1, 1], 'swing'],
      [OFF_W, [1.04, 0.95], 'standard'], [OFF_END - 4, [0.98, 1.02], 'swing'], [OFF_END, [1, 1], 'swing'],
    ]),
  });
  const ring = draw('ring', {
    paths: [ellipse(C, track<Vec2>([11, 11]).hold(13).to(27, [30, 30], 'emphasized'))],
    stroke: { tone: 'tint', width: track(2.6).hold(13).to(27, 0, 'emphasized'), opacity: track(0).to(13, 1, 'hold').to(27, 0, 'hold') },
  });
  const particles = Array.from({ length: 8 }, (_, n): SceneNode => {
    const big = n % 2 === 0;
    const a = 22.5 + n * 45;
    const size = big ? 2.6 : 1.5;
    return draw(`particle ${n}`, {
      paths: [ellipse(
        track(polar(C, big ? 8.5 : 7.5, a)).hold(14).to(30, polar(C, big ? 15.5 : 12.5, a), 'enter'),
        track<Vec2>([size, size]).hold(20).to(31, [0, 0], 'exit'),
      )],
      fill: { tone: big ? 'tint' : 'ink', opacity: track(0).to(14, 1, 'hold') },
    });
  });
  const burst = group('burst', [ring, ...particles], { pivot: C, rotation: track(0).hold(14).to(32, 14, 'enter') });
  return compose({ name: 'Heart', frames: OFF_END, scene: [burst, body], markers: { on: [0, END], off: [END, OFF_END] } });
}

/* ── Sun ⇄ moon ────────────────────────────────────────────────────────────────────────────────────────────────
   The rays shorten and the sun swells (wind-up); the rays fold away in a sweep starting next to the coming bite,
   the disc grows into a full moon and a bite sweeps across it from the right to leave a crescent; two stars twinkle
   in after it. Reversible as it stands. */
function crescent(c1: Vec2, r1: number, biteDeg: number, d: number, r2: number): { path: Path; angles: number[] } {
  const c2 = polar(c1, d, biteDeg);
  const beta = (Math.acos((r1 * r1 - r2 * r2 + d * d) / (2 * d * r1)) * 180) / Math.PI;
  const start = biteDeg + beta, end = biteDeg - beta + 360;
  const outer = arc(c1, r1, start, end, 4);
  const about = (p: Vec2, c: Vec2): number => (Math.atan2(p[0] - c[0], -(p[1] - c[1])) * 180) / Math.PI;
  // Inner edge: the part of the bite circle inside the moon, from the last cusp back to the first, through the
  // point of the bite circle nearest the moon's centre (so it bulges inward).
  const from = about(outer.v[4], c2);
  let to = about(outer.v[0], c2);
  const via = biteDeg + 180;
  const norm = (x: number) => ((x % 360) + 360) % 360;
  const cw = norm(via - from) < norm(to - from); // does going clockwise from `from` reach `via` before `to`?
  to = cw ? from + norm(to - from) : from - norm(from - to);
  const inner = arc(c2, r2, from, to, 2);
  const path: Path = {
    v: [...outer.v, inner.v[1]],
    i: [inner.i[2], outer.i[1], outer.i[2], outer.i[3], outer.i[4], inner.i[1]],
    o: [outer.o[0], outer.o[1], outer.o[2], outer.o[3], inner.o[0], inner.o[1]],
    c: true,
  };
  // Sun vertices at the outer vertices' angles; the inner vertex sits midway between the cusps, on the bite side,
  // so morphing sun → moon drives it straight across the disc: the bite sweeps in.
  const angles = [...outer.v.map((p) => about(p, c1)), biteDeg];
  return { path, angles };
}

function sparkle(c: Vec2, r: number): Path {
  const tips = [0, 90, 180, 270].map((a) => polar(c, r, a));
  const pull = (p: Vec2): Vec2 => [(c[0] - p[0]) * 0.62, (c[1] - p[1]) * 0.62];
  return { v: tips, i: tips.map(pull), o: tips.map(pull), c: true };
}

function theme(w: number): LottieAnimation {
  const W = 9, END = 42;
  const C: Vec2 = [12, 12];
  const moon = crescent(C, 8.2, 45, 4.6, 6.4);
  const disc = (r: number): Path => ellipseAt(C, r, r, moon.angles);
  // Staged: the sun gathers (wind-up), the rays fold into it, then the disc swells into a full moon and is bitten.
  const body = draw('body', {
    paths: [track(disc(4.4)).to(W, disc(4.1), 'standard').hold(13).to(21, disc(7.6), 'inOut').to(31, moon.path, 'emphasized')],
    stroke: { tone: 'ink', width: w },
  });
  const orb = group('orb', [body], {
    pivot: C,
    rotation: track(32).hold(13).to(33, 0, 'emphasized'),
    scale: track(1).hold(25).to(30, 1.05, 'standard').to(37, 1, 'swing'),
  });
  const order = [45, 0, 90, 315, 135, 270, 180, 225]; // fold from the bite side round to the far side
  const rays = order.map((a, n): SceneNode => {
    const t0 = W + 1 + n * 0.8;
    return draw(`ray ${a}`, {
      paths: [track(line(polar(C, 7.2, a), polar(C, 9.6, a))).to(W, line(polar(C, 7, a), polar(C, 8.9, a)), 'standard').hold(t0).to(t0 + 5, line(polar(C, 6.6, a), polar(C, 6.7, a)), 'exit')],
      stroke: { tone: 'ink', width: w, opacity: track(1).hold(t0 + 2).to(t0 + 5, 0, 'linear') },
    });
  });
  const rayGroup = group('rays', rays, { pivot: C, rotation: track(0).to(W, -12, 'standard').to(W + 12, -36, 'standard') });
  const star = (name: string, c: Vec2, r: number, t0: number): SceneNode => draw(name, {
    paths: [sparkle(c, r)],
    fill: { tone: 'tint' },
    transform: {
      pivot: c,
      scale: track(0).hold(t0).to(t0 + 6, 1.25, 'emphasized').to(t0 + 11, 1, 'swing'),
      rotation: track(-45).hold(t0).to(t0 + 11, 0, 'emphasized'),
    },
  });
  return compose({
    name: 'Sun / moon', frames: END,
    scene: [rayGroup, orb, star('star', [19.4, 4.6], 2.6, 27), star('star small', [21.5, 10.6], 1.6, 31)],
    markers: { on: [0, END] },
  });
}

export const ICONS: Record<IconId, IconDesign> = {
  menu: { id: 'menu', segments: { on: [0, 32], hover: { on: WIND, off: 10 } }, build: menu },
  play: { id: 'play', segments: { on: [0, 30], hover: { on: 8, off: 8 } }, build: play },
  bookmark: { id: 'bookmark', segments: { on: [0, 42], off: [42, 58], hover: { on: WIND, off: 6 } }, build: bookmark },
  bell: { id: 'bell', segments: { on: [0, 42], off: [42, 62], hover: { on: 8, off: 6 } }, build: bell },
  heart: { id: 'heart', segments: { on: [0, 34], off: [34, 50], hover: { on: 9, off: 6 } }, build: heart },
  theme: { id: 'theme', segments: { on: [0, 42], hover: { on: 9, off: 8 } }, build: theme },
};

/**
 * lottie-kit — author original Lottie (Bodymovin 5.x) animations as typed code, and render any frame of them as a
 * static SVG tree (used as the fallback before lottie-web loads, or where it cannot run).
 *
 * Authoring model, SVG-like:
 *   - A scene is a tree of `group`s and `draw`s listed bottom → top (later children paint on top).
 *   - A `draw` holds paths painted by an optional fill and an optional stroke (the stroke sits above the fill).
 *   - Any value can be a constant or a `track(...)`: `.to(frame, value, ease)` eases from the previous key INTO the
 *     new one with a motion token (`'overshoot'`, `'emphasized'` …), `'swing'` (half a cosine) or `'hold'` (a jump).
 *   - Path morphs are tracks of `Path`s; every key must keep the same vertex count (checked when compiling).
 *
 * Colours are not baked in. Each paint names a tone (ink, tint, solid, on, knock) that is emitted as class names on the
 * SVG element lottie-web creates (`cl: "lmi-st lmi-ink"`), and CSS maps tones to theme tokens. One data file therefore
 * follows light, dark and any local theme without being rebuilt. The RGB values in the data are only a fallback.
 */
import { easing, type Bezier, type EasingToken } from '../../motion';

/* ── Values, keyframe tracks and easing ─────────────────────────────────────────────────────────────────────── */

export type Vec2 = readonly [number, number];
export type Ease = EasingToken | Bezier | 'swing' | 'hold';

/** One pendulum swing between two turning points: zero velocity at both ends (half a cosine). */
export const SWING: Bezier = [0.37, 0, 0.63, 1];

const bezierFor = (e: Exclude<Ease, 'hold'>): Bezier => (typeof e === 'string' ? (e === 'swing' ? SWING : easing[e]) : e);

export interface Key<T> { t: number; v: T; ease: Ease }

/** A keyframe track. The ease of a key describes how the value ARRIVES at it from the previous key. */
export class Track<T> {
  readonly keys: Key<T>[];
  constructor(v: T, t = 0) { this.keys = [{ t, v, ease: 'linear' }]; }
  get end(): Key<T> { return this.keys[this.keys.length - 1]; }
  /** Ease from the previous key into `v`, arriving at frame `t`. */
  to(t: number, v: T, ease: Ease = 'standard'): this {
    if (!(t > this.end.t)) throw new Error(`lottie-kit: keys must move forward in time (${t} after ${this.end.t})`);
    this.keys.push({ t, v, ease });
    return this;
  }
  /** Keep the current value until frame `t`. */
  hold(t: number): this { return t > this.end.t ? this.to(t, this.end.v, 'linear') : this; }
  /** Append a sequence of `[frame, value, ease]` keys. */
  keysTo(list: readonly (readonly [number, T, Ease?])[]): this {
    for (const [t, v, e] of list) this.to(t, v, e ?? 'standard');
    return this;
  }
}
export const track = <T>(v: T, t = 0): Track<T> => new Track<T>(v, t);
export type Anim<T> = T | Track<T>;

/**
 * Turning points of a damped oscillation released from `amplitude` (a struck bell, a plucked ribbon): one key per
 * swing, each `halfPeriod` frames after the last and `decay` times smaller, eased with `SWING`, ending at 0.
 */
export function oscillation(from: number, amplitude: number, opts: { start: number; halfPeriod: number; decay: number; swings: number }): readonly (readonly [number, number, Ease])[] {
  const out: [number, number, Ease][] = [];
  let a = amplitude;
  let t = opts.start;
  for (let n = 0; n < opts.swings; n++) {
    t += opts.halfPeriod;
    out.push([Math.round(t * 10) / 10, from + a, 'swing']);
    a *= -opts.decay;
  }
  out.push([Math.round((t + opts.halfPeriod) * 10) / 10, from, 'swing']);
  return out;
}

/* ── Geometry on the design grid ─────────────────────────────────────────────────────────────────────────────── */

/** A bezier path. Tangents are relative to their vertex (Lottie's convention): `i` before the vertex, `o` after it. */
export interface Path { readonly v: readonly Vec2[]; readonly i: readonly Vec2[]; readonly o: readonly Vec2[]; readonly c: boolean }

const Z: Vec2 = [0, 0];
const add = (a: Vec2, b: Vec2): Vec2 => [a[0] + b[0], a[1] + b[1]];
const sub = (a: Vec2, b: Vec2): Vec2 => [a[0] - b[0], a[1] - b[1]];
const mul = (a: Vec2, s: number): Vec2 => [a[0] * s, a[1] * s];
const len = (a: Vec2): number => Math.hypot(a[0], a[1]);
const unit = (a: Vec2): Vec2 => { const l = len(a) || 1; return [a[0] / l, a[1] / l]; };
const rad = (deg: number): number => (deg * Math.PI) / 180;
/** Point at `deg` clockwise from 12 o'clock (screen space, y down). */
export const polar = (c: Vec2, r: number, deg: number, ry = r): Vec2 => [c[0] + r * Math.sin(rad(deg)), c[1] - ry * Math.cos(rad(deg))];

/** Straight segments through `points`. */
export function polyline(points: readonly Vec2[], closed = false): Path {
  return { v: points.slice(), i: points.map(() => Z), o: points.map(() => Z), c: closed };
}
export const line = (a: Vec2, b: Vec2): Path => polyline([a, b]);

/**
 * Closed polygon whose corners are true circular arcs. Every corner emits two vertices (arc start, arc end), so two
 * polygons with the same corner count always morph cleanly, whatever their radii (0 keeps a sharp corner).
 */
export function roundedPolygon(points: readonly Vec2[], radius: number | readonly number[]): Path {
  const n = points.length;
  const v: Vec2[] = [], i: Vec2[] = [], o: Vec2[] = [];
  for (let k = 0; k < n; k++) {
    const p = points[k], prev = points[(k + n - 1) % n], next = points[(k + 1) % n];
    const r = typeof radius === 'number' ? radius : radius[k] ?? 0;
    const u1 = unit(sub(prev, p)), u2 = unit(sub(next, p));
    const theta = Math.acos(Math.min(1, Math.max(-1, u1[0] * u2[0] + u1[1] * u2[1])));
    let d = r > 0 && theta > 1e-3 ? r / Math.tan(theta / 2) : 0;
    d = Math.min(d, len(sub(prev, p)) / 2, len(sub(next, p)) / 2);
    const h = (4 / 3) * Math.tan((Math.PI - theta) / 4) * d * Math.tan(theta / 2);
    v.push(add(p, mul(u1, d)), add(p, mul(u2, d)));
    i.push(Z, mul(u2, -h));
    o.push(mul(u1, -h), Z);
  }
  return { v, i, o, c: true };
}

/**
 * Smooth closed curve through points at the given angles (degrees clockwise from 12 o'clock) of an ellipse. With
 * evenly spaced angles it is a circle; with the angles of another shape's vertices it becomes a morph target that
 * travels to that shape without twisting.
 */
export function ellipseAt(c: Vec2, rx: number, ry: number, anglesDeg: readonly number[]): Path {
  const n = anglesDeg.length;
  const a = anglesDeg.map(rad);
  const v: Vec2[] = [], i: Vec2[] = [], o: Vec2[] = [];
  for (let k = 0; k < n; k++) {
    const gPrev = ((a[k] - a[(k + n - 1) % n]) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) || 2 * Math.PI;
    const gNext = ((a[(k + 1) % n] - a[k]) % (2 * Math.PI) + 2 * Math.PI) % (2 * Math.PI) || 2 * Math.PI;
    const tan: Vec2 = [Math.cos(a[k]), Math.sin(a[k])]; // clockwise tangent on the unit circle
    const hIn = (4 / 3) * Math.tan(gPrev / 4), hOut = (4 / 3) * Math.tan(gNext / 4);
    v.push([c[0] + rx * Math.sin(a[k]), c[1] - ry * Math.cos(a[k])]);
    i.push([-tan[0] * rx * hIn, -tan[1] * ry * hIn]);
    o.push([tan[0] * rx * hOut, tan[1] * ry * hOut]);
  }
  return { v, i, o, c: true };
}

/** Circle with `n` evenly spaced vertices, the first at `startDeg` (clockwise from 12 o'clock). */
export const circle = (c: Vec2, r: number, n = 4, startDeg = 0): Path =>
  ellipseAt(c, r, r, Array.from({ length: n }, (_, k) => startDeg + (360 / n) * k));

/** Open circular arc from `fromDeg` to `toDeg` (clockwise from 12 o'clock) in `segments` bezier segments. */
export function arc(c: Vec2, r: number, fromDeg: number, toDeg: number, segments = 1): Path {
  const step = (toDeg - fromDeg) / segments;
  const h = (4 / 3) * Math.tan(rad(step) / 4) * r;
  const v: Vec2[] = [], i: Vec2[] = [], o: Vec2[] = [];
  for (let k = 0; k <= segments; k++) {
    const d = rad(fromDeg + step * k);
    const tan: Vec2 = [Math.cos(d), Math.sin(d)];
    v.push(polar(c, r, fromDeg + step * k));
    i.push(k === 0 ? Z : mul(tan, -h));
    o.push(k === segments ? Z : mul(tan, h));
  }
  return { v, i, o, c: false };
}

/** Angles (clockwise from 12 o'clock, about `c`) of a path's vertices — for building a matching morph target. */
export const vertexAngles = (p: Path, c: Vec2): number[] =>
  p.v.map(([x, y]) => (Math.atan2(x - c[0], -(y - c[1])) * 180) / Math.PI);

/** Move every vertex of a path (tangents unchanged). */
export const translatePath = (p: Path, d: Vec2): Path => ({ ...p, v: p.v.map((q) => add(q, d)) });

/* ── Scene ───────────────────────────────────────────────────────────────────────────────────────────────────── */

/** Paint roles. CSS maps them to tokens: line art, the "activated" colour, a solid disc, the glyph on it, a knock-out. */
export type Tone = 'ink' | 'tint' | 'solid' | 'on' | 'knock';

export interface Ellipse { readonly kind: 'ellipse'; readonly center: Anim<Vec2>; readonly size: Anim<Vec2> }
export const ellipse = (center: Anim<Vec2>, size: Anim<Vec2>): Ellipse => ({ kind: 'ellipse', center, size });

export interface FillPaint { tone: Tone; opacity?: Anim<number> }
export interface StrokePaint { tone: Tone; width: Anim<number>; opacity?: Anim<number>; cap?: 'butt' | 'round' | 'square'; join?: 'miter' | 'round' | 'bevel' }
/** Rotation and scale happen about `pivot` (anchor = position = pivot), unless `anchor`/`position` are given. */
export interface Transform { pivot?: Vec2; anchor?: Anim<Vec2>; position?: Anim<Vec2>; scale?: Anim<number> | Anim<Vec2>; rotation?: Anim<number>; opacity?: Anim<number> }

export type SceneNode =
  | { kind: 'draw'; name: string; paths: readonly (Anim<Path> | Ellipse)[]; fill?: FillPaint; stroke?: StrokePaint; transform?: Transform }
  | { kind: 'group'; name: string; children: readonly SceneNode[]; transform?: Transform };

export const draw = (name: string, spec: { paths: readonly (Anim<Path> | Ellipse)[]; fill?: FillPaint; stroke?: StrokePaint; transform?: Transform }): SceneNode => ({ kind: 'draw', name, ...spec });
export const group = (name: string, children: readonly SceneNode[], transform?: Transform): SceneNode => ({ kind: 'group', name, children, transform });

/* ── Lottie JSON (the subset this kit writes and the static renderer reads) ─────────────────────────────────── */

export interface LottieEase { x: number | number[]; y: number | number[] }
export interface LottieKeyframe { t: number; s?: unknown[]; e?: unknown[]; o?: LottieEase; i?: LottieEase; h?: number }
export interface LottieProp { a: 0 | 1; k: unknown; ix?: number }
export interface LottieShapePath { c: boolean; v: number[][]; i: number[][]; o: number[][] }
export interface LottieItem { ty: string; nm?: string; [key: string]: unknown }
export interface LottieLayer { ddd: 0; ind: number; ty: number; nm: string; sr: 1; ks: Record<string, unknown>; ao: 0; shapes: LottieItem[]; ip: number; op: number; st: 0; bm: 0 }
export interface LottieMarker { tm: number; cm: string; dr: number }
export interface LottieAnimation { v: string; fr: number; ip: number; op: number; w: number; h: number; nm: string; ddd: 0; assets: unknown[]; layers: LottieLayer[]; markers: LottieMarker[]; __complete?: boolean }

const TONE_RGB: Record<Tone, readonly [number, number, number]> = {
  ink: [0x11, 0x11, 0x0f], tint: [0xbf, 0x2f, 0x09], solid: [0x11, 0x11, 0x0f], on: [0xfb, 0xf9, 0xf4], knock: [0xfb, 0xf9, 0xf4],
};
const toneColor = (t: Tone): LottieProp => ({ a: 0, k: [...TONE_RGB[t].map((c) => Math.round((c / 255) * 1000) / 1000), 1] });
const r3 = (n: number): number => Math.round(n * 1000) / 1000;

/** Constant or keyframed Lottie property. Keyframe values are arrays (`[45]`, `[x, y]`, `[shape]`). */
function encode<T, O>(a: Anim<T>, enc: (v: T) => O, shape = false): LottieProp {
  if (!(a instanceof Track) || a.keys.length === 1) {
    const v = a instanceof Track ? a.keys[0].v : a;
    return { a: 0, k: enc(v) };
  }
  const keys = a.keys;
  return {
    a: 1,
    k: keys.map((key, n): LottieKeyframe => {
      const e: unknown = enc(key.v);
      const kf: LottieKeyframe = { t: key.t, s: Array.isArray(e) && !shape ? e : [e] };
      const next = keys[n + 1];
      if (next) {
        if (next.ease === 'hold') kf.h = 1;
        else {
          const [x1, y1, x2, y2] = bezierFor(next.ease);
          kf.o = shape ? { x: x1, y: y1 } : { x: [x1], y: [y1] };
          kf.i = shape ? { x: x2, y: y2 } : { x: [x2], y: [y2] };
        }
      }
      return kf;
    }),
  };
}
const vec = (v: Vec2): number[] => [r3(v[0]), r3(v[1])];
const scaleVec = (v: number | Vec2): number[] => (typeof v === 'number' ? [r3(v * 100), r3(v * 100)] : [r3(v[0] * 100), r3(v[1] * 100)]);
const shapeJson = (p: Path): LottieShapePath => ({ c: p.c, v: p.v.map(vec), i: p.i.map(vec), o: p.o.map(vec) });

function transformJson(t: Transform = {}): LottieItem {
  const pivot = t.pivot ?? [0, 0];
  return {
    ty: 'tr',
    nm: 'Transform',
    a: encode(t.anchor ?? pivot, vec),
    p: encode(t.position ?? pivot, vec),
    s: encode<number | Vec2, number[]>(t.scale ?? 1, scaleVec),
    r: encode(t.rotation ?? 0, (n) => r3(n)),
    o: encode(t.opacity ?? 1, (n) => r3(n * 100)),
    sk: { a: 0, k: 0 },
    sa: { a: 0, k: 0 },
  };
}

function checkMorph(name: string, p: Anim<Path>): void {
  if (!(p instanceof Track)) return;
  const [first, ...rest] = p.keys;
  for (const k of rest) {
    if (k.v.v.length !== first.v.v.length || k.v.c !== first.v.c) {
      throw new Error(`lottie-kit: "${name}" morphs between paths with different vertex counts (${first.v.v.length} → ${k.v.v.length} at frame ${k.t})`);
    }
  }
}

function nodeJson(node: SceneNode): LottieItem {
  if (node.kind === 'group') {
    return { ty: 'gr', nm: node.name, it: [...[...node.children].reverse().map(nodeJson), transformJson(node.transform)], np: node.children.length + 1, cix: 2, bm: 0, hd: false };
  }
  const it: LottieItem[] = node.paths.map((p, n) => {
    if (typeof p === 'object' && 'kind' in p && p.kind === 'ellipse') {
      return { ty: 'el', nm: `${node.name} ellipse ${n}`, d: 1, p: encode(p.center, vec), s: encode(p.size, vec) };
    }
    const path = p as Anim<Path>;
    checkMorph(node.name, path);
    return { ty: 'sh', nm: `${node.name} path ${n}`, d: 1, ks: encode(path, shapeJson, true) };
  });
  if (node.stroke) {
    const s = node.stroke;
    it.push({ ty: 'st', nm: `${node.name} stroke`, cl: `lmi-st lmi-${s.tone}`, c: toneColor(s.tone), o: encode(s.opacity ?? 1, (n) => r3(n * 100)), w: encode(s.width, (n) => r3(n)), lc: { butt: 1, round: 2, square: 3 }[s.cap ?? 'round'], lj: { miter: 1, round: 2, bevel: 3 }[s.join ?? 'round'], ml: 4, bm: 0 });
  }
  if (node.fill) {
    it.push({ ty: 'fl', nm: `${node.name} fill`, cl: `lmi-fl lmi-${node.fill.tone}`, c: toneColor(node.fill.tone), o: encode(node.fill.opacity ?? 1, (n) => r3(n * 100)), r: 1, bm: 0 });
  }
  it.push(transformJson(node.transform));
  return { ty: 'gr', nm: node.name, it, np: it.length, cix: 2, bm: 0, hd: false };
}

export interface ComposeSpec {
  name: string;
  /** Last authored frame (the timeline runs 0 … frames). */
  frames: number;
  fps?: number;
  /** Design grid in composition units (24 for a 24-unit icon). */
  grid?: number;
  /** Empty margin around the grid, in grid units, so bursts and overshoot are not clipped. */
  bleed?: number;
  scene: readonly SceneNode[];
  /** Named segments, written as Lottie markers (the convention After Effects exports use). */
  markers?: Record<string, readonly [number, number]>;
}

/** Compile a scene into a Lottie animation: one shape layer, the grid offset by `bleed` inside the composition. */
export function compose(spec: ComposeSpec): LottieAnimation {
  const grid = spec.grid ?? 24;
  const bleed = spec.bleed ?? 8;
  const size = grid + bleed * 2;
  // One frame of headroom past the last key: a forward segment that ends ON a frame needs to be played to frame + 1.
  const op = spec.frames + 2;
  const root = group('root', spec.scene, { position: [bleed, bleed] });
  return {
    v: '5.12.0', fr: spec.fps ?? 60, ip: 0, op, w: size, h: size, nm: spec.name, ddd: 0, assets: [],
    layers: [{
      ddd: 0, ind: 1, ty: 4, nm: spec.name, sr: 1, ao: 0, ip: 0, op, st: 0, bm: 0,
      ks: { o: { a: 0, k: 100 }, r: { a: 0, k: 0 }, p: { a: 0, k: [0, 0, 0] }, a: { a: 0, k: [0, 0, 0] }, s: { a: 0, k: [100, 100, 100] } },
      shapes: [nodeJson(root)],
    }],
    markers: Object.entries(spec.markers ?? {}).map(([cm, [a, b]]) => ({ tm: a, cm, dr: b - a })),
  };
}

/* ── Static renderer: any frame of the data above as an SVG tree ────────────────────────────────────────────── */

export interface SvgNode { tag: 'g' | 'path'; attrs: Record<string, string>; children?: SvgNode[] }

/** The cubic-bezier solver lottie-web uses (bezier-easing by G. Renaudeau), so fallback frames match the player. */
function bezierEasing(x1: number, y1: number, x2: number, y2: number): (x: number) => number {
  if (x1 === y1 && x2 === y2) return (x) => x;
  const A = (a1: number, a2: number) => 1 - 3 * a2 + 3 * a1;
  const B = (a1: number, a2: number) => 3 * a2 - 6 * a1;
  const C = (a1: number) => 3 * a1;
  const calc = (t: number, a1: number, a2: number) => ((A(a1, a2) * t + B(a1, a2)) * t + C(a1)) * t;
  const slope = (t: number, a1: number, a2: number) => 3 * A(a1, a2) * t * t + 2 * B(a1, a2) * t + C(a1);
  const N = 11, step = 1 / (N - 1);
  const samples = Array.from({ length: N }, (_, k) => calc(k * step, x1, x2));
  const tForX = (x: number): number => {
    let start = 0, k = 1;
    for (; k !== N - 1 && samples[k] <= x; k++) start += step;
    k--;
    const guess = start + ((x - samples[k]) / (samples[k + 1] - samples[k])) * step;
    const s = slope(guess, x1, x2);
    if (s >= 0.001) {
      let t = guess;
      for (let n = 0; n < 4; n++) { const sl = slope(t, x1, x2); if (sl === 0) return t; t -= (calc(t, x1, x2) - x) / sl; }
      return t;
    }
    if (s === 0) return guess;
    let a = start, b = start + step, t = 0, cx = 0, n = 0;
    do { t = a + (b - a) / 2; cx = calc(t, x1, x2) - x; if (cx > 0) b = t; else a = t; } while (Math.abs(cx) > 1e-7 && ++n < 10);
    return t;
  };
  return (x) => (x === 0 ? 0 : x === 1 ? 1 : calc(tForX(x), y1, y2));
}
const pick = (v: number | number[] | undefined, d: number): number => (Array.isArray(v) ? (v[d] ?? v[0]) : (v ?? 0));
function progress(kf: LottieKeyframe, d: number, p: number): number {
  if (!kf.o || !kf.i) return p;
  return bezierEasing(pick(kf.o.x, d), pick(kf.o.y, d), pick(kf.i.x, d), pick(kf.i.y, d))(p);
}

/** Find the active keyframe pair: [from, to, local progress 0…1] (lottie-web's lookup rules, holds included). */
function span(k: LottieKeyframe[], f: number): [LottieKeyframe, LottieKeyframe | null, number] {
  if (f < k[0].t) return [k[0], null, 0];
  const last = k[k.length - 1];
  if (f >= last.t) return [last.s ? last : { ...k[k.length - 2], s: k[k.length - 2].e }, null, 0];
  let n = 0;
  while (n < k.length - 2 && k[n + 1].t <= f) n++;
  const a = k[n], b = k[n + 1];
  if (a.h === 1) return [a, null, 0];
  return [a, b, (f - a.t) / (b.t - a.t)];
}

function num(prop: unknown, f: number, fallback: number[]): number[] {
  const p = prop as LottieProp | undefined;
  if (!p) return fallback;
  if (!p.a) return Array.isArray(p.k) ? (p.k as number[]) : [p.k as number];
  const [a, b, t] = span(p.k as LottieKeyframe[], f);
  const from = (a.s ?? a.e ?? fallback) as number[];
  if (!b) return from;
  const to = (b.s ?? a.e ?? from) as number[];
  return from.map((v, d) => v + (to[d] - v) * progress(a, d, t));
}

function shapeAt(prop: unknown, f: number): LottieShapePath {
  const p = prop as LottieProp;
  if (!p.a) return p.k as LottieShapePath;
  const [a, b, t] = span(p.k as LottieKeyframe[], f);
  const from = (a.s ?? a.e)![0] as LottieShapePath;
  if (!b) return from;
  const to = ((b.s ?? a.e)![0]) as LottieShapePath;
  const e = progress(a, 0, t);
  const lerp = (x: number[][], y: number[][]) => x.map((q, n) => [q[0] + (y[n][0] - q[0]) * e, q[1] + (y[n][1] - q[1]) * e]);
  return { c: from.c, v: lerp(from.v, to.v), i: lerp(from.i, to.i), o: lerp(from.o, to.o) };
}

const fmt = (n: number): string => String(Math.round(n * 1000) / 1000);

function pathD(s: LottieShapePath, absolute: boolean): string {
  const n = s.v.length;
  if (!n) return '';
  const ctl = (k: number, t: number[][]) => (absolute ? t[k] : [s.v[k][0] + t[k][0], s.v[k][1] + t[k][1]]);
  let d = `M${fmt(s.v[0][0])},${fmt(s.v[0][1])}`;
  const seg = (a: number, b: number) => {
    const o = ctl(a, s.o), i = ctl(b, s.i);
    d += `C${fmt(o[0])},${fmt(o[1])} ${fmt(i[0])},${fmt(i[1])} ${fmt(s.v[b][0])},${fmt(s.v[b][1])}`;
  };
  for (let k = 1; k < n; k++) seg(k - 1, k);
  if (s.c) { seg(n - 1, 0); d += 'z'; }
  return d;
}

/** Ellipse as lottie-web draws it: four bezier quadrants from 12 o'clock, clockwise. */
function ellipseD(item: LottieItem, f: number): string {
  const [cx, cy] = num(item.p, f, [0, 0]);
  const [w, h] = num(item.s, f, [0, 0]);
  if (!w && !h) return '';
  const rx = w / 2, ry = h / 2, k = 0.5519;
  const P = (x: number, y: number) => `${fmt(x)},${fmt(y)}`;
  return `M${P(cx, cy - ry)}C${P(cx + rx * k, cy - ry)} ${P(cx + rx, cy - ry * k)} ${P(cx + rx, cy)}`
    + `C${P(cx + rx, cy + ry * k)} ${P(cx + rx * k, cy + ry)} ${P(cx, cy + ry)}`
    + `C${P(cx - rx * k, cy + ry)} ${P(cx - rx, cy + ry * k)} ${P(cx - rx, cy)}`
    + `C${P(cx - rx, cy - ry * k)} ${P(cx - rx * k, cy - ry)} ${P(cx, cy - ry)}z`;
}

/** SVG `matrix()` for a Lottie transform: translate(p) · rotate(r) · scale(s) · translate(−a). */
function matrixOf(tr: Record<string, unknown>, f: number): { m: string; opacity: number } {
  const p = tr.p as { s?: boolean; x?: unknown; y?: unknown } | undefined;
  const [px, py] = p && p.s ? [num(p.x, f, [0])[0], num(p.y, f, [0])[0]] : num(tr.p, f, [0, 0]);
  const [ax, ay] = num(tr.a, f, [0, 0]);
  const [sx, sy] = num(tr.s, f, [100, 100]).map((v) => v / 100);
  const r = rad(num(tr.r, f, [0])[0]);
  const cos = Math.cos(r), sin = Math.sin(r);
  const a = cos * sx, b = sin * sx, c = -sin * sy, d = cos * sy;
  const e = px - (a * ax + c * ay), g = py - (b * ax + d * ay);
  return { m: `matrix(${[a, b, c, d, e, g].map(fmt).join(',')})`, opacity: num(tr.o, f, [100])[0] / 100 };
}

const rgb = (prop: unknown, f: number): string => {
  const [r, g, b] = num(prop, f, [0, 0, 0]);
  return `rgb(${Math.floor(r * 255)},${Math.floor(g * 255)},${Math.floor(b * 255)})`;
};

function renderItems(items: LottieItem[], f: number, absolute: boolean): SvgNode[] {
  const out: SvgNode[] = [];
  // Lottie lists items top-first: walk bottom-up so later output paints on top.
  for (let n = items.length - 1; n >= 0; n--) {
    const it = items[n];
    if (it.hd === true) continue;
    if (it.ty === 'gr') {
      const its = it.it as LottieItem[];
      const tr = its.find((x) => x.ty === 'tr');
      const { m, opacity } = tr ? matrixOf(tr, f) : { m: 'matrix(1,0,0,1,0,0)', opacity: 1 };
      out.push({ tag: 'g', attrs: { transform: m, opacity: fmt(opacity) }, children: renderItems(its, f, absolute) });
    } else if (it.ty === 'fl' || it.ty === 'st') {
      // A style paints every path listed above it in the same group.
      const d = items.slice(0, n).map((s) => (s.hd === true ? '' : s.ty === 'sh' ? pathD(shapeAt(s.ks, f), absolute) : s.ty === 'el' ? ellipseD(s, f) : '')).join('');
      const attrs: Record<string, string> = { d: d || 'M0 0' };
      if (typeof it.cl === 'string') attrs.class = it.cl;
      const o = fmt(num(it.o, f, [100])[0] / 100);
      if (it.ty === 'fl') {
        Object.assign(attrs, { fill: rgb(it.c, f), 'fill-opacity': o });
        if (it.r === 2) attrs['fill-rule'] = 'evenodd';
      } else {
        Object.assign(attrs, {
          fill: 'none', stroke: rgb(it.c, f), 'stroke-opacity': o, 'stroke-width': fmt(num(it.w, f, [1])[0]),
          'stroke-linecap': ['butt', 'butt', 'round', 'square'][Number(it.lc ?? 2)] ?? 'round',
          'stroke-linejoin': ['miter', 'miter', 'round', 'bevel'][Number(it.lj ?? 2)] ?? 'round',
        });
      }
      out.push({ tag: 'path', attrs });
    }
  }
  return out;
}

/**
 * Render one frame of a Lottie animation (shape layers: groups, paths, ellipses, fills, strokes, transforms) as an SVG
 * tree in composition coordinates. Exact at keyframes; between keys it follows lottie-web's interpolation.
 */
export function renderFrame(anim: LottieAnimation, frame: number): SvgNode[] {
  const absolute = anim.__complete === true; // data already processed by lottie-web holds absolute tangents
  const out: SvgNode[] = [];
  for (let n = anim.layers.length - 1; n >= 0; n--) {
    const layer = anim.layers[n];
    if (layer.ty !== 4 || frame < layer.ip || frame >= layer.op) continue;
    const { m, opacity } = matrixOf(layer.ks, frame);
    out.push({ tag: 'g', attrs: { transform: m, opacity: fmt(opacity) }, children: renderItems(layer.shapes, frame, absolute) });
  }
  return out;
}

/* LottieIcon: a button reset, the icon box and the tone → token mapping. Consumers style the button via className. */
.button {
  position: relative;
  display: inline-grid;
  place-items: center;
  min-width: 44px;
  min-height: 44px;
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.button:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }

/* The icon box is the design grid; the player and fallback overhang it by the composition's bleed. */
.glyph {
  position: relative;
  display: block;
  flex: none;
  width: var(--lmi-size, 24px);
  height: var(--lmi-size, 24px);
  pointer-events: none;
}
.player, .fallback {
  position: absolute;
  top: calc(var(--lmi-size, 24px) * var(--lmi-bleed, 0) * -1);
  left: calc(var(--lmi-size, 24px) * var(--lmi-bleed, 0) * -1);
  display: block;
  width: calc(var(--lmi-size, 24px) * (1 + 2 * var(--lmi-bleed, 0)));
  height: calc(var(--lmi-size, 24px) * (1 + 2 * var(--lmi-bleed, 0)));
  overflow: visible;
}
.player :global(svg) { display: block; overflow: visible; }
.ghost { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.glyph[data-ready] .fallback { display: none; }

/* Tones. Colours in the Lottie data are only a fallback: CSS beats SVG presentation attributes, so every tagged
   fill and stroke follows the theme (and any local token override) live, with no rebuild. */
.glyph :global(.lmi-st.lmi-ink) { stroke: var(--lmi-ink, var(--mk-ink, #11110f)); }
.glyph :global(.lmi-fl.lmi-ink) { fill: var(--lmi-ink, var(--mk-ink, #11110f)); }
.glyph :global(.lmi-st.lmi-tint) { stroke: var(--lmi-tint, var(--mk-accent, #bf2f09)); }
.glyph :global(.lmi-fl.lmi-tint) { fill: var(--lmi-tint, var(--mk-accent, #bf2f09)); }
.glyph :global(.lmi-st.lmi-solid) { stroke: var(--lmi-solid, var(--lmi-ink, var(--mk-ink, #11110f))); }
.glyph :global(.lmi-fl.lmi-solid) { fill: var(--lmi-solid, var(--lmi-ink, var(--mk-ink, #11110f))); }
.glyph :global(.lmi-st.lmi-on) { stroke: var(--lmi-on, var(--mk-surface, #fbf9f4)); }
.glyph :global(.lmi-fl.lmi-on) { fill: var(--lmi-on, var(--mk-surface, #fbf9f4)); }
.glyph :global(.lmi-st.lmi-knock) { stroke: var(--lmi-knock, var(--mk-surface, #fbf9f4)); }
.glyph :global(.lmi-fl.lmi-knock) { fill: var(--lmi-knock, var(--mk-surface, #fbf9f4)); }

@media (forced-colors: active) {
  .glyph :global(.lmi-st) { stroke: CanvasText; }
  .glyph :global(.lmi-fl) { fill: CanvasText; }
  .glyph :global(.lmi-st.lmi-knock), .glyph :global(.lmi-st.lmi-on) { stroke: Canvas; }
  .glyph :global(.lmi-fl.lmi-on) { fill: Canvas; }
}

'use client';
/**
 * LottieIcon — a real toggle button (aria-pressed) or disclosure button (aria-expanded) whose icon is a Lottie
 * animation played in segments. Content-agnostic: pass any Bodymovin JSON plus its segment map.
 *
 * - lottie-web's light SVG player is imported lazily, once, on first mount; each icon owns one instance, destroyed
 *   on unmount. Until it is ready (or where it cannot run) a static SVG of the rest frame is shown instead.
 * - Colours come from CSS: fills and strokes tagged `lmi-fl|lmi-st` + `lmi-ink|tint|solid|on|knock` (see
 *   ./lottie-kit) follow the theme tokens live; untagged shapes keep the colours in the data.
 * - Reduced motion: no hover previews; state changes jump to the rest frame under a 160 ms cross-fade.
 * - `ref` reaches the <button>, and `data-*` / `aria-*` props land on it (a cursor magnet, a View Transition origin,
 *   aria-describedby); the state attributes the icon owns (aria-pressed / aria-expanded / aria-controls, its name and
 *   data-state) always win.
 */
import { createElement, useEffect, useImperativeHandle, useMemo, useRef, useState, type AriaAttributes, type CSSProperties, type ReactNode, type Ref } from 'react';
import type { LottiePlayer } from 'lottie-web/build/player/lottie_light';
import { duration, useIsomorphicLayoutEffect, useStudioMotion } from '../../motion';
import { renderFrame, type LottieAnimation, type SvgNode } from './lottie-kit';
import { IconPlayer, type PlayerSnapshot } from './player';
import type { LottieSegments } from './segments';
import styles from './LottieIcon.module.css';

let lottieReady: LottiePlayer | null = null;
let lottieLoading: Promise<LottiePlayer> | null = null;

/** lottie-web's light SVG player, loaded on first use and shared by every icon. */
function loadLottie(): Promise<LottiePlayer> {
  // A plain promise chain (no await) so nothing outside lottie-web owns the module's evaluation.
  lottieLoading ??= import('lottie-web/build/player/lottie_light').then((m) => {
    const lottie = ((m as { default?: LottiePlayer }).default ?? m) as LottiePlayer;
    if (typeof lottie?.loadAnimation !== 'function') throw new Error('lottie-web is not available here');
    lottieReady = lottie;
    return lottie;
  });
  return lottieLoading;
}

export interface LottieIconHandle {
  /** Show any frame (direct manipulation). */
  scrub: (frame: number) => void;
  /** End a scrub: play from the shown frame to the rest pose of the current state. */
  release: () => void;
}

/** `data-*` attributes, passed to the button. */
type DataAttributes = { [key: `data-${string}`]: string | number | boolean | undefined };

export interface LottieIconProps extends AriaAttributes, DataAttributes {
  /** Bodymovin JSON. It is copied before lottie-web sees it (the player mutates its input). Keep it referentially stable. */
  animationData: object;
  /** Frame ranges of the transitions and the hover wind-up. */
  segments: LottieSegments;
  /** Accessible name. Constant: the state is carried by aria-pressed / aria-expanded. */
  label: string;
  /** Controlled state. Omit to let the button keep its own (starting at `defaultPressed`). */
  pressed?: boolean;
  defaultPressed?: boolean;
  onToggle?: (pressed: boolean) => void;
  /** `toggle` → aria-pressed; `disclosure` → aria-expanded (+ `controls`). */
  kind?: 'toggle' | 'disclosure';
  controls?: string;
  /** Rendered size in px of the design grid (`grid` composition units; the rest of the composition is bleed). */
  size?: number;
  grid?: number;
  /** Playback rate (1 = authored timing). */
  speed?: number;
  /** Preview the wind-up on hover and keyboard focus. */
  hover?: boolean;
  /** Force reduced motion on or off; defaults to useStudioMotion().reduced. */
  reduced?: boolean;
  /** Shown until lottie-web paints, and wherever it cannot run. `'auto'` renders the rest frame of shape-layer data. */
  fallback?: ReactNode | 'auto';
  className?: string;
  style?: CSSProperties;
  /** Visible content after the icon (a caption). When present it names the button and `label` is not used. */
  children?: ReactNode;
  /** Called with the frame on screen while the icon plays or is scrubbed. */
  onFrame?: (frame: number) => void;
  handle?: Ref<LottieIconHandle>;
  /** The <button> element. */
  ref?: Ref<HTMLButtonElement>;
}

/** Only `data-*` and `aria-*` keys reach the DOM from the rest props. */
function passThrough(rest: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const k in rest) if (k.startsWith('data-') || k.startsWith('aria-')) out[k] = rest[k];
  return out;
}

const ATTR: Record<string, string> = {
  class: 'className', 'fill-opacity': 'fillOpacity', 'fill-rule': 'fillRule', 'stroke-opacity': 'strokeOpacity',
  'stroke-width': 'strokeWidth', 'stroke-linecap': 'strokeLinecap', 'stroke-linejoin': 'strokeLinejoin',
};
const toReact = (n: SvgNode, key: number): ReactNode => {
  const props: Record<string, string | number> = { key };
  for (const [k, v] of Object.entries(n.attrs)) props[ATTR[k] ?? k] = v;
  return createElement(n.tag, props, ...(n.children ?? []).map(toReact));
};

/** Fade a frozen copy of the current drawing over the new one (reduced motion: no movement, just a short cross-fade). */
function crossfade(host: HTMLElement | null, live: Set<Animation>, apply: () => void): void {
  const svg = host?.querySelector('svg');
  if (!host || !svg || typeof svg.animate !== 'function') { apply(); return; }
  const ghost = svg.cloneNode(true) as SVGSVGElement;
  ghost.querySelectorAll('[id]').forEach((el) => el.removeAttribute('id'));
  ghost.removeAttribute('id');
  ghost.setAttribute('class', styles.ghost);
  host.appendChild(ghost);
  apply();
  const a = ghost.animate([{ opacity: 1 }, { opacity: 0 }], { duration: duration.fast, easing: 'linear', fill: 'forwards' });
  live.add(a);
  const done = () => { live.delete(a); ghost.remove(); };
  a.finished.then(done, done);
}

export function LottieIcon({
  animationData, segments, label, pressed: controlled, defaultPressed = false, onToggle, kind = 'toggle', controls,
  size = 32, grid, speed = 1, hover = true, reduced: reducedProp, fallback = 'auto', className, style, children, onFrame, handle,
  ref, ...rest
}: LottieIconProps) {
  const motion = useStudioMotion();
  const reduced = reducedProp ?? motion.reduced;
  const [own, setOwn] = useState(defaultPressed);
  const pressed = controlled ?? own;
  const data = animationData as LottieAnimation;

  const hostRef = useRef<HTMLSpanElement>(null);
  const glyphRef = useRef<HTMLSpanElement>(null);
  const playerRef = useRef<IconPlayer | null>(null);
  const resume = useRef<PlayerSnapshot | null>(null);
  const engaged = useRef({ pointer: false, focus: false });
  const ghosts = useRef(new Set<Animation>());
  const latest = useRef({ pressed, speed, hover, reduced, segments, onFrame });
  latest.current = { pressed, speed, hover, reduced, segments, onFrame };

  // One lottie instance per icon, rebuilt only when the data changes (keeping its frame); destroyed on unmount.
  useEffect(() => {
    const host = hostRef.current;
    const glyph = glyphRef.current;
    if (!host || !glyph) return;
    let alive = true;
    let player: IconPlayer | null = null;
    const stop = () => {
      player?.dispose();
      player = null;
      playerRef.current = null;
      glyph.removeAttribute('data-ready');
    };
    const start = (lottie: LottiePlayer) => {
      if (!alive) return;
      try {
        const copy = JSON.parse(JSON.stringify(data)) as LottieAnimation;
        const anim = lottie.loadAnimation({
          container: host, renderer: 'svg', loop: false, autoplay: false, animationData: copy,
          rendererSettings: { preserveAspectRatio: 'xMidYMid meet', progressiveLoad: false, hideOnTransparent: true },
        });
        anim.addEventListener('error', stop);
        anim.addEventListener('data_failed', stop);
        const s = latest.current;
        player = new IconPlayer(anim, s.segments, s.pressed, copy.op, (f) => latest.current.onFrame?.(f));
        player.setSpeed(s.speed);
        player.setHoverEnabled(s.hover && !s.reduced);
        if (resume.current) player.restore(resume.current);
        player.pointer(engaged.current.pointer);
        player.focus(engaged.current.focus);
        playerRef.current = player;
        if (anim.isLoaded) glyph.setAttribute('data-ready', '');
        else anim.addEventListener('DOMLoaded', () => { if (player) glyph.setAttribute('data-ready', ''); });
      } catch {
        stop();
      }
    };
    if (lottieReady) start(lottieReady);
    else loadLottie().then(start, () => { /* stays on the static fallback */ });
    const live = ghosts.current;
    return () => {
      alive = false;
      resume.current = player ? player.snapshot() : null;
      for (const a of live) a.cancel();
      stop();
    };
  }, [data]);

  // State changes: animate from the frame on screen, or cross-fade to the rest frame when motion is reduced.
  useIsomorphicLayoutEffect(() => {
    const p = playerRef.current;
    if (!p) return;
    if (latest.current.reduced) crossfade(hostRef.current, ghosts.current, () => p.setPressed(pressed, false));
    else p.setPressed(pressed, true);
  }, [pressed]);

  const segKey = JSON.stringify(segments);
  useEffect(() => { playerRef.current?.setSpeed(speed); }, [speed]);
  useEffect(() => { playerRef.current?.setSegments(latest.current.segments); }, [segKey]);
  useEffect(() => {
    const p = playerRef.current;
    if (!p) return;
    p.setHoverEnabled(hover && !reduced);
    if (reduced) p.jumpToRest();
  }, [hover, reduced]);

  useImperativeHandle(handle, () => ({
    scrub: (frame: number) => playerRef.current?.scrub(frame),
    release: () => {
      const p = playerRef.current;
      if (!p) return;
      if (latest.current.reduced) crossfade(hostRef.current, ghosts.current, () => p.release(false));
      else p.release();
    },
  }), []);

  const restFrame = pressed ? segments.on[1] : segments.on[0];
  const auto = fallback === 'auto';
  const staticArt = useMemo(() => {
    if (!auto) return null;
    try { return renderFrame(data, restFrame).map(toReact); } catch { return null; }
  }, [auto, data, restFrame]);

  const box = grid ?? data.w;
  const bleed = Math.max(0, (data.w - box) / 2 / box);
  const engage = (key: 'pointer' | 'focus', on: boolean) => {
    engaged.current[key] = on;
    if (key === 'pointer') playerRef.current?.pointer(on);
    else playerRef.current?.focus(on);
  };

  return (
    <button
      {...passThrough(rest)}
      ref={ref}
      type="button"
      className={className ? `${styles.button} ${className}` : styles.button}
      style={{ ...style, '--lmi-size': `${size}px`, '--lmi-bleed': bleed } as CSSProperties}
      aria-pressed={kind === 'toggle' ? pressed : undefined}
      aria-expanded={kind === 'disclosure' ? pressed : undefined}
      aria-controls={kind === 'disclosure' ? controls : undefined}
      aria-label={children ? undefined : label}
      data-state={pressed ? 'on' : 'off'}
      onClick={() => {
        const next = !pressed;
        if (controlled === undefined) setOwn(next);
        onToggle?.(next);
      }}
      onPointerEnter={(e) => { if (e.pointerType !== 'touch') engage('pointer', true); }}
      onPointerLeave={() => engage('pointer', false)}
      onFocus={(e) => {
        let keyboard = false;
        try { keyboard = e.currentTarget.matches(':focus-visible'); } catch { /* engines without :focus-visible */ }
        if (keyboard) engage('focus', true);
      }}
      onBlur={() => engage('focus', false)}
    >
      <span ref={glyphRef} className={styles.glyph} aria-hidden="true">
        <span ref={hostRef} className={styles.player} />
        {auto ? (
          staticArt ? <svg className={styles.fallback} viewBox={`0 0 ${data.w} ${data.h}`} focusable="false">{staticArt}</svg> : null
        ) : fallback ? <span className={styles.fallback}>{fallback}</span> : null}
      </span>
      {children}
    </button>
  );
}

/**
 * IconPlayer — drives one lottie-web AnimationItem as a two-state icon.
 *
 * Every move starts from the frame on screen: a toggle plays forward or backward from wherever the icon is (mid
 * wind-up, mid transition, mid release), so it can be interrupted and reversed at any frame and nothing is queued.
 * Hover/focus plays the wind-up of the next transition and holds it; the click then continues from that frame.
 * lottie-web only ticks while an instance plays, so an idle icon costs nothing.
 */
import type { AnimationItem } from 'lottie-web/build/player/lottie_light';
import { duration } from '../../motion';
import type { LottieSegments } from './segments';

type Mode = 'rest' | 'preview' | 'release' | 'toggle' | 'scrub';
const EPS = 0.01;
/**
 * A hover preview plays the wind-up in the `fast` token's time. When a toggle starts straight from rest (touch,
 * keyboard, a quick click), the same frames are compressed into the `instant` token's time so the commit lands sooner.
 */
const BRISK = duration.fast / duration.instant;

export interface PlayerSnapshot { frame: number; mode: Mode }

export class IconPlayer {
  private mode: Mode = 'rest';
  private target: number | null = null;
  private pressed: boolean;
  private hovered = false;
  private focused = false;
  /** A preview may start. Cleared by a toggle, re-armed when pointer and focus have both left. */
  private armed = true;
  private hoverEnabled = true;
  private speed = 1;
  /** While set, the wind-up plays at BRISK × speed until the frame passes `until` in direction `dir`. */
  private brisk: { until: number; dir: 1 | -1 } | null = null;
  private readonly onComplete = (): void => this.landed();
  private readonly onEnterFrame = (): void => {
    const f = this.frame();
    if (this.brisk && (this.brisk.dir > 0 ? f >= this.brisk.until : f <= this.brisk.until)) this.calm();
    this.listener?.(f);
  };

  constructor(
    private readonly anim: AnimationItem,
    private segments: LottieSegments,
    pressed: boolean,
    /** Composition out point: the whole timeline is [0, op]. */
    private readonly op: number,
    private readonly listener?: (frame: number) => void,
  ) {
    this.pressed = pressed;
    anim.addEventListener('complete', this.onComplete);
    anim.addEventListener('enterFrame', this.onEnterFrame); // lottie only emits it while playing or seeking
    this.seek(this.rest());
  }

  /** Absolute frame on screen (lottie reports frames relative to the current segment). */
  frame(): number { return this.anim.firstFrame + this.anim.currentFrame; }
  get lastFrame(): number { return (this.segments.off ?? this.segments.on)[1]; }
  private rest(): number { return this.pressed ? this.segments.on[1] : this.segments.on[0]; }

  private calm(): void {
    if (!this.brisk) return;
    this.brisk = null;
    this.anim.setSpeed(this.speed);
  }

  private seek(frame: number): void {
    this.calm();
    this.anim.setSegment(0, this.op);
    this.anim.goToAndStop(frame, true);
  }

  /** Play from the current frame to `to`. lottie stops a forward segment one frame early, so aim one frame past. */
  private playTo(to: number): void {
    this.calm();
    const from = this.frame();
    this.target = to;
    if (Math.abs(from - to) < 0.5) { this.seek(to); this.landed(); return; }
    this.anim.playSegments(to > from ? [from, to + 1] : [from, to], true);
  }

  private landed(): void {
    const to = this.target;
    this.target = null;
    if (to === null) return;
    const off = this.segments.off;
    // The end of the off transition looks exactly like the start of the on one: park there so the next toggle can
    // play `on` forward again.
    this.seek(off && Math.abs(to - off[1]) < EPS ? this.segments.on[0] : to);
    if (this.mode === 'toggle' || this.mode === 'release') this.mode = 'rest';
  }

  /** Animate to the rest pose of the logical state, choosing the direction from the current frame. */
  private settle(): void {
    const [a, b] = this.segments.on;
    const off = this.segments.off;
    const f = this.frame();
    if (this.pressed) {
      if (off && f >= off[1] - EPS) this.seek(a);
      this.playTo(b); // forward through `on`, or backward through `off` when interrupted mid-way
    } else {
      this.playTo(off && f >= b - EPS ? off[1] : a);
    }
  }

  setPressed(next: boolean, animate: boolean): void {
    if (next === this.pressed) return;
    const fromRest = this.mode === 'rest';
    this.pressed = next;
    this.armed = false;
    if (!animate) { this.jumpToRest(); return; }
    this.mode = 'toggle';
    this.settle();
    if (fromRest && this.target !== null) this.hurryWindUp();
  }

  /** Compress the wind-up of a transition that starts at rest (see BRISK). */
  private hurryWindUp(): void {
    const [a, b] = this.segments.on;
    const off = this.segments.off;
    const n = (this.pressed ? this.segments.hover?.on : this.segments.hover?.off) ?? 0;
    if (n <= 0) return;
    const f = this.frame();
    const end = this.pressed ? a + n : off ? b + n : b - n;
    const dir: 1 | -1 = end >= f ? 1 : -1;
    if (Math.abs(end - f) < 0.5) return;
    this.brisk = { until: end, dir };
    this.anim.setSpeed(this.speed * BRISK);
  }

  /** Stop wherever the icon is and show the rest pose of the current state (reduced motion). */
  jumpToRest(): void {
    this.mode = 'rest';
    this.target = null;
    this.seek(this.rest());
  }

  pointer(over: boolean): void { this.hovered = over; this.engage(); }
  focus(on: boolean): void { this.focused = on; this.engage(); }

  private engage(): void {
    if (!this.hovered && !this.focused) {
      this.armed = true;
      if (this.mode === 'preview') { this.mode = 'release'; this.playTo(this.rest()); }
      return;
    }
    if ((this.mode !== 'rest' && this.mode !== 'release') || !this.armed || !this.hoverEnabled) return;
    const [a, b] = this.segments.on;
    const n = (this.pressed ? this.segments.hover?.off : this.segments.hover?.on) ?? 0;
    if (n <= 0) return;
    this.mode = 'preview';
    this.playTo(this.pressed ? (this.segments.off ? b + n : b - n) : a + n);
  }

  setHoverEnabled(on: boolean): void {
    this.hoverEnabled = on;
    if (!on && this.mode === 'preview') { this.mode = 'release'; this.playTo(this.rest()); }
  }

  setSpeed(speed: number): void {
    this.speed = Math.max(0.05, speed);
    this.anim.setSpeed(this.brisk ? this.speed * BRISK : this.speed);
  }

  setSegments(segments: LottieSegments): void {
    this.segments = segments;
    if (this.mode === 'rest') this.seek(this.rest());
  }

  /** Direct manipulation: show any frame. `release()` then plays to the rest pose of the current state. */
  scrub(frame: number): void {
    this.mode = 'scrub';
    this.target = null;
    this.seek(Math.min(this.lastFrame, Math.max(0, frame)));
  }

  release(animate = true): void {
    if (this.mode !== 'scrub') return;
    if (!animate) { this.jumpToRest(); return; }
    this.mode = 'toggle';
    this.settle();
  }

  snapshot(): PlayerSnapshot { return { frame: this.frame(), mode: this.mode }; }

  /** Continue from another instance's state (the data was rebuilt): same frame, same intent. */
  restore(s: PlayerSnapshot): void {
    this.seek(s.frame);
    if (s.mode === 'preview') { this.mode = 'preview'; this.armed = true; return; }
    this.mode = 'toggle';
    this.settle();
  }

  dispose(): void {
    this.brisk = null;
    this.anim.removeEventListener('complete', this.onComplete);
    this.anim.removeEventListener('enterFrame', this.onEnterFrame);
    this.anim.destroy();
  }
}

/**
 * Segment map of an interactive Lottie icon.
 *
 *   off rest ──on──▶ on rest ──off──▶ off rest (same pose as on[0])
 *   frame on[0]       on[1] = off[0]   off[1]
 *
 * `hover.on` / `hover.off` are the first frames of the transition that hover and keyboard focus preview and hold
 * (the wind-up); a click continues from that exact frame, so preview and commit never fight. Without `off`, the `on`
 * transition plays backwards to switch off, and the off-state preview plays the last `hover.off` frames of it backwards.
 */
export interface LottieSegments {
  on: readonly [number, number];
  off?: readonly [number, number];
  hover?: { readonly on?: number; readonly off?: number };
}

/* ── Layout ────────────────────────────────────────────────────────────────────────────────────────────────── */
.root {
  box-sizing: border-box;
  container-type: inline-size;
  width: 100%;
  padding: clamp(18px, 5cqi, 44px) clamp(16px, 4cqi, 40px);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
.layout { display: grid; justify-items: center; gap: 32px; margin: 0 auto; }
@container (min-width: 760px) {
  .layout {
    grid-template-columns: minmax(0, 392px) minmax(0, 380px);
    justify-content: center;
    align-items: center;
    column-gap: clamp(36px, 6cqi, 80px);
  }
}
.column { display: grid; justify-items: center; gap: 14px; width: 100%; max-width: 392px; }

/* ── Card (a fictional podcast player) ─────────────────────────────────────────────────────────────────────── */
.card {
  --pad: clamp(14px, 4.4cqi, 22px);
  position: relative;
  box-sizing: border-box;
  display: grid;
  gap: 16px;
  width: 100%;
  padding: var(--pad);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: calc(var(--mk-radius-l, 18px) + 4px);
  background: var(--mk-surface, #fbf9f4);
  color: var(--mk-ink, #11110f);
  /* Light from above: a hairline highlight on the top edge, a tight contact shadow and a wide soft one. */
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.05),
    0 1px 2px rgb(0 0 0 / 0.07),
    0 22px 44px -26px rgb(0 0 0 / 0.42);
  transition:
    background-color var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease),
    color var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease),
    border-color var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease);
}
/* Icons take their colours from CSS, so they follow these tokens with no rebuild. */
.card :global(.lmi-st), .card :global(.lmi-fl) {
  transition: fill var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease), stroke var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease);
}
/* Tint param: which tokens the icon tones use. Declared on the card so night-mode tokens resolve here. */
.card[data-tint='accent'] { --lmi-ink: var(--mk-accent, #bf2f09); --lmi-solid: var(--mk-accent, #bf2f09); --lmi-on: var(--mk-on-signal, #ffffff); }
.card[data-tint='ink'] { --lmi-tint: var(--mk-ink, #11110f); }
/* Night mode: a local palette for the card only. */
.card[data-night] {
  --mk-surface: #121a2e;
  --mk-surface-2: #1b2540;
  --mk-ink: #eef2fb;
  --mk-ink-muted: #a2adc6;
  --mk-line: #eef2fb29;
  --mk-line-strong: #eef2fb;
  --mk-signal: #ffb84d;
  --mk-accent: #ffb84d;
  --mk-on-signal: #121a2e;
  --mk-focus: #8ab4ff;
  background: var(--mk-surface);
  color: var(--mk-ink);
  border-color: var(--mk-line);
}

/* ── App bar ───────────────────────────────────────────────────────────────────────────────────────────────── */
.bar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 6px;
  margin: calc(var(--pad) * -0.45) calc(var(--pad) * -0.45) 0;
}
.brand { display: grid; gap: 1px; min-width: 0; margin: 0; padding-left: 2px; }
.show {
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(0.8125rem, 4cqi, 0.9375rem);
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.2;
}
.sample, .kicker, .times, .count, .queueTitle, .queueNo, .queueMin, .hint {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  letter-spacing: 0.06em;
}
.sample {
  overflow: hidden;
  font-size: 0.625rem;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--mk-ink-muted, #5c5a52);
}
.barEnd { display: flex; gap: 2px; }
.iconButton {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  transition: box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
/* Hover is a hairline ring, not a fill: the bell's knock-out gap stays the colour of the card behind it. */
@media (hover: hover) {
  .iconButton:hover, .pill:hover { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 24%, transparent); }
}

/* ── Queue (disclosure content): a popover under the bar, so opening it never moves the card ─────────────────── */
.queue {
  position: absolute;
  z-index: 3;
  top: calc(var(--pad) * 0.55 + 50px);
  left: calc(var(--pad) * 0.55);
  right: calc(var(--pad) * 0.55);
  padding: 12px 16px 4px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface, #fbf9f4);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.05), 0 1px 2px rgb(0 0 0 / 0.08), 0 26px 50px -22px rgb(0 0 0 / 0.5);
  transform-origin: 22px 0;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px) scale(0.96);
  /* Exit: quicker than the entrance, accelerating away. */
  transition:
    opacity var(--mk-duration-fast, 160ms) var(--mk-ease-exit, ease-in),
    transform var(--mk-duration-fast, 160ms) var(--mk-ease-exit, ease-in),
    background-color var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease),
    visibility 0s linear var(--mk-duration-fast, 160ms);
}
.queue[data-open] {
  opacity: 1;
  visibility: visible;
  transform: none;
  /* Entrance: settles on spring.settle (sampled into linear()). */
  transition:
    opacity var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease),
    transform var(--settle-duration, 360ms) var(--settle-ease, ease),
    background-color var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease),
    visibility 0s;
}
.queueTitle {
  margin: 0;
  padding-bottom: 8px;
  font-size: 0.625rem;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}
.queueList { display: grid; margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--mk-line, #11110f24); }
.queueList li {
  display: grid;
  grid-template-columns: 1.75rem minmax(0, 1fr) auto;
  align-items: baseline;
  gap: 8px;
  padding: 10px 0;
  font-size: 0.875rem;
  opacity: 0;
  translate: 0 -4px;
  transition: opacity var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), translate var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.queueList li + li { border-top: 1px solid var(--mk-line, #11110f24); }
.queue[data-open] .queueList li {
  opacity: 1;
  translate: 0 0;
  transition-duration: var(--mk-duration-moderate, 360ms);
  transition-timing-function: var(--mk-ease-emphasized, ease);
}
.queue[data-open] .queueList li:nth-child(1) { transition-delay: 40ms; }
.queue[data-open] .queueList li:nth-child(2) { transition-delay: calc(40ms + var(--mk-stagger-base, 48ms)); }
.queue[data-open] .queueList li:nth-child(3) { transition-delay: calc(40ms + 2 * var(--mk-stagger-base, 48ms)); }
.queueNo, .queueMin { font-size: 0.6875rem; color: var(--mk-ink-muted, #5c5a52); font-variant-numeric: tabular-nums; }
.queueName { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ── Now playing ───────────────────────────────────────────────────────────────────────────────────────────── */
.now { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: 14px; }
.cover {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: clamp(64px, 19cqi, 84px);
  aspect-ratio: 1;
  border-radius: 14px;
  background: linear-gradient(172deg, #f8e6c9 0%, #f2bb8d 50%, #d4704c 100%);
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.07), 0 8px 18px -10px rgb(0 0 0 / 0.5);
}
.cover::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(172deg, #2a3a66 0%, #17244a 55%, #0d1532 100%);
  opacity: 0;
  transition: opacity var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease);
}
.card[data-night] .cover::after { opacity: 1; }
.sun, .moon {
  position: absolute;
  z-index: 1;
  left: 50%;
  top: 36%;
  aspect-ratio: 1;
  border-radius: 50%;
  translate: -50% -50%;
  transition: transform var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, ease), opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease);
}
.sun { width: 34%; background: #fff3dc; box-shadow: 0 0 0 5px rgb(255 243 220 / 0.28); }
.moon { width: 30%; box-shadow: inset -7px 4px 0 0 #f3ead6; transform: translateY(90%) rotate(-30deg); opacity: 0; }
.card[data-night] .sun { transform: translateY(95%); opacity: 0; }
.card[data-night] .moon { transform: none; opacity: 1; transition-delay: 120ms; }
.waves { position: absolute; z-index: 2; left: 0; right: 0; bottom: 0; width: 100%; height: 46%; }
.waves path {
  fill: none;
  stroke: rgb(86 42 26 / 0.5);
  stroke-width: 1.6;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
  transition: stroke var(--mk-duration-slow, 560ms) var(--mk-ease-standard, ease);
}
.card[data-night] .waves path { stroke: rgb(170 194 255 / 0.5); }
.meta { display: grid; gap: 4px; min-width: 0; }
.kicker { margin: 0; font-size: 0.625rem; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.title {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.0625rem, 4.4cqi, 1.3125rem);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.025em;
  text-wrap: balance;
}
.byline { margin: 0; font-size: 0.8125rem; color: var(--mk-ink-muted, #5c5a52); }

/* ── Progress (static sample) ──────────────────────────────────────────────────────────────────────────────── */
.progress { display: grid; gap: 9px; }
.track { position: relative; height: 4px; border-radius: 99px; background: color-mix(in oklab, var(--mk-ink, #11110f) 14%, transparent); }
.fill { position: absolute; inset: 0 auto 0 0; width: 32%; border-radius: inherit; background: var(--mk-ink, #11110f); }
.knob {
  position: absolute;
  top: 50%;
  left: 32%;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  translate: -50% -50%;
  background: var(--mk-ink, #11110f);
  box-shadow: 0 0 0 3px var(--mk-surface, #fbf9f4);
}
.times {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 0;
  font-size: 0.6875rem;
  font-variant-numeric: tabular-nums;
  color: var(--mk-ink-muted, #5c5a52);
}
.status { display: inline-flex; align-items: center; gap: 7px; color: var(--mk-ink, #11110f); }
.eq { display: inline-flex; align-items: flex-end; gap: 2px; height: 10px; }
.eq i { display: block; width: 2px; height: 100%; border-radius: 1px; background: currentColor; transform-origin: 50% 100%; transform: scaleY(0.3); }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .card[data-playing] .eq i { animation: eq var(--mk-duration-cinematic, 900ms) var(--mk-ease-inOut, ease-in-out) infinite alternate; }
  .root:not([data-reduced]) .card[data-playing] .eq i:nth-child(2) { animation-delay: calc(var(--mk-duration-cinematic, 900ms) * -0.45); }
  .root:not([data-reduced]) .card[data-playing] .eq i:nth-child(3) { animation-delay: calc(var(--mk-duration-cinematic, 900ms) * -0.8); }
}
.card[data-playing] .eq i { transform: scaleY(0.7); }
@keyframes eq { from { transform: scaleY(0.25); } to { transform: scaleY(1); } }

/* ── Controls ──────────────────────────────────────────────────────────────────────────────────────────────── */
.controls { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 6px; }
.side { display: flex; align-items: center; gap: 2px; min-width: 0; }
.sideEnd { justify-content: flex-end; }
.pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 46px;
  padding: 0 14px 0 9px;
  border-radius: 999px;
  transition: box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.caption { font-size: 0.875rem; font-weight: 600; letter-spacing: -0.005em; transition: color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
.pill[aria-pressed='true'] .caption { color: var(--lmi-tint, var(--mk-accent, #bf2f09)); }
/* Narrow cards: captions sit under their icons (tab-bar style) so large icon sizes still fit beside the play disc. */
@container (max-width: 480px) {
  .pill { flex-direction: column; justify-content: center; gap: 3px; height: auto; min-height: 52px; padding: 5px 10px; border-radius: 16px; }
  .caption { font-size: 0.75rem; }
}
.count { display: inline-flex; flex: none; overflow: hidden; font-size: 0.75rem; font-variant-numeric: tabular-nums; color: var(--mk-ink-muted, #5c5a52); }
.countRoll { display: inline-block; }
/* The count rolls with the like: up when it grows, down when it shrinks (a secondary action to the heart). */
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .countRoll[data-dir='up'] { animation: rollUp var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease) 120ms both; }
  .root:not([data-reduced]) .countRoll[data-dir='down'] { animation: rollDown var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease) both; }
}
@keyframes rollUp { from { transform: translateY(80%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes rollDown { from { transform: translateY(-60%); opacity: 0; } to { transform: none; opacity: 1; } }
.primary { border-radius: 50%; }
/* The disc is part of the Lottie drawing; its shadow follows the drawn silhouette, lifting on hover, pressing down. */
.primary > span:first-child {
  filter: drop-shadow(0 1px 1px rgb(0 0 0 / 0.16)) drop-shadow(0 7px 9px rgb(0 0 0 / 0.16));
  transition: filter var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
@media (hover: hover) {
  .primary:hover > span:first-child { filter: drop-shadow(0 1px 1px rgb(0 0 0 / 0.14)) drop-shadow(0 11px 14px rgb(0 0 0 / 0.2)); }
}
.primary:active > span:first-child { filter: drop-shadow(0 1px 0 rgb(0 0 0 / 0.2)) drop-shadow(0 3px 4px rgb(0 0 0 / 0.14)); }
/* Press depth: in within a frame, out on a spring (spring.press sampled into linear()). */
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .iconButton > span:first-child,
  .root:not([data-reduced]) .pill > span:first-child,
  .root:not([data-reduced]) .primary > span:first-child {
    transition: transform var(--press-duration, 360ms) var(--press-ease, ease), filter var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
  }
  .root:not([data-reduced]) .iconButton:active > span:first-child,
  .root:not([data-reduced]) .pill:active > span:first-child,
  .root:not([data-reduced]) .primary:active > span:first-child {
    transform: scale(0.93);
    transition-duration: var(--mk-duration-instant, 90ms);
  }
}
.hint {
  max-width: 46ch;
  margin: 0;
  font-size: 0.625rem;
  line-height: 1.6;
  text-align: center;
  text-transform: uppercase;
  text-wrap: balance;
  color: var(--mk-ink-muted, #5c5a52);
}

/* ── Timeline ──────────────────────────────────────────────────────────────────────────────────────────────── */
.timeline { display: grid; gap: 10px; width: 100%; max-width: 392px; }
.timelineHead {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px 16px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--mk-line-strong, #11110f);
}
.timelineTitle, .legend, .laneName, .frameNo {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.timelineTitle { margin: 0; font-weight: 600; }
.timelineTitle span { margin-left: 8px; font-weight: 400; color: var(--mk-ink-muted, #5c5a52); }
.legend { display: flex; gap: 12px; margin: 0; padding: 0; list-style: none; color: var(--mk-ink-muted, #5c5a52); }
.legend li { display: inline-flex; align-items: center; gap: 6px; }
.legend li::before { content: ''; width: 12px; height: 4px; border-radius: 2px; }
.legend li[data-kind='wind']::before, .seg[data-kind='wind'] {
  background: repeating-linear-gradient(90deg, var(--mk-ink-muted, #5c5a52) 0 2px, transparent 2px 4px);
}
.legend li[data-kind='on']::before, .seg[data-kind='on'] { background: var(--mk-ink, #11110f); }
.legend li[data-kind='off']::before, .seg[data-kind='off'] {
  background: repeating-linear-gradient(90deg, var(--mk-ink, #11110f) 0 6px, transparent 6px 8px);
}
.lanes { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
.lane { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr) 1.75rem; align-items: center; gap: 12px; }
.laneName { color: var(--mk-ink, #11110f); }
.laneTrack { position: relative; height: 32px; border-radius: 4px; }
.laneTrack:has(.scrubber:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 1px; }
.seg { position: absolute; top: 50%; height: 4px; border-radius: 2px; translate: 0 -50%; }
.head {
  position: absolute;
  top: 6px;
  bottom: 6px;
  left: calc(var(--pos, 0) * 100%);
  width: 2px;
  border-radius: 1px;
  translate: -50% 0;
  background: var(--mk-signal, #bf2f09);
  pointer-events: none;
}
.head::before {
  content: '';
  position: absolute;
  top: -3px;
  left: 50%;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  translate: -50% 0;
  background: var(--mk-signal, #bf2f09);
  box-shadow: 0 0 0 2px var(--mk-surface, #fbf9f4);
}
.scrubber {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: ew-resize;
}
.frameNo { text-align: right; font-variant-numeric: tabular-nums; color: var(--mk-ink-muted, #5c5a52); }

.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }

/* ── Reduced motion: state changes stay (cross-fades inside the icons), travel and ambient motion go ─────────── */
.root[data-reduced] .queue { transform: none; transition: opacity var(--mk-duration-fast, 160ms) linear, visibility 0s linear var(--mk-duration-fast, 160ms); }
.root[data-reduced] .queue[data-open] { transition: opacity var(--mk-duration-fast, 160ms) linear, visibility 0s; }
.root[data-reduced] .queueList li { translate: none; transition: none; }
.root[data-reduced] .sun, .root[data-reduced] .moon { transform: none; transition: opacity var(--mk-duration-fast, 160ms) linear; }
/* Palette swaps (night mode, theme) are state changes: a short fade at most. */
.root[data-reduced] .card, .root[data-reduced] .card :global(.lmi-st), .root[data-reduced] .card :global(.lmi-fl),
.root[data-reduced] .cover::after, .root[data-reduced] .waves path { transition-duration: var(--mk-duration-fast, 160ms); }
@media (prefers-reduced-motion: reduce) {
  .card, .card :global(.lmi-st), .card :global(.lmi-fl), .cover::after, .waves path { transition-duration: var(--mk-duration-fast, 160ms); }
  .queue { transform: none; }
  .queueList li { translate: none; transition: none; }
  .sun, .moon { transform: none !important; }
}

'use client';
/**
 * Timeline — one lane per icon showing its segments (wind-up, on, off) and a live playhead fed by the icon's
 * enterFrame events (lottie only emits them while playing or seeking, so an idle timeline does no work). Each lane is
 * a native range input: drag it, or focus it and use the arrow keys, to scrub the icon frame by frame; letting go
 * (pointer up, or focus leaving the lane) plays the icon from that frame back to its current state.
 *
 * Playheads are written straight to the DOM. Lanes are found through one stable list ref (not per-lane ref callbacks,
 * which React detaches and re-attaches on every render and would miss a frame written from a layout effect).
 */
import { useId, useImperativeHandle, useRef, type CSSProperties, type Ref } from 'react';
import type { LottieSegments } from './segments';
import styles from './styles.module.css';

export interface TimelineLane {
  id: string;
  name: string;
  segments: LottieSegments;
  /** Frame the icon rests on right now (on[0] or on[1]). Only the first value seeds the lane. */
  rest: number;
  scrub: (frame: number) => void;
  release: () => void;
}
export interface TimelineApi { update: (id: string, frame: number) => void }

const two = (n: number): string => String(Math.round(n)).padStart(2, '0');
const STEP_KEYS = new Set(['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown']);
const valueText = (f: number, last: number): string => `Frame ${Math.round(f)} of ${last}`;

export function Timeline({ lanes, api, fps }: { lanes: readonly TimelineLane[]; api: Ref<TimelineApi>; fps: number }) {
  const uid = useId();
  const list = useRef<HTMLOListElement>(null);
  /** Lanes being scrubbed by the user: their input is the source of truth, so playback does not overwrite it. */
  const scrubbing = useRef(new Set<string>());
  /** First rest frame per lane: seeds the markup once; afterwards everything is written per frame. */
  const seed = useRef(new Map<string, number>());

  const show = (id: string, frame: number, syncInput: boolean) => {
    const li = list.current?.querySelector<HTMLLIElement>(`[data-lane="${id}"]`);
    if (!li) return;
    const last = Number(li.dataset.last) || 1;
    li.style.setProperty('--pos', String(Math.min(1, Math.max(0, frame / last))));
    const out = li.querySelector<HTMLElement>('[data-frame]');
    if (out) out.textContent = two(frame);
    const input = li.querySelector<HTMLInputElement>('input');
    if (input && syncInput) {
      input.value = String(frame);
      input.setAttribute('aria-valuetext', valueText(frame, last));
    }
  };

  useImperativeHandle(api, () => ({ update: (id, frame) => show(id, frame, !scrubbing.current.has(id)) }), []);

  return (
    <section className={styles.timeline} aria-labelledby={`${uid}h`}>
      <header className={styles.timelineHead}>
        <h4 id={`${uid}h`} className={styles.timelineTitle}>Timeline <span>{fps} fps</span></h4>
        <ul className={styles.legend} aria-label="Segments">
          <li data-kind="wind">wind&#8209;up</li><li data-kind="on">on</li><li data-kind="off">off</li>
        </ul>
      </header>
      <ol ref={list} className={styles.lanes}>
        {lanes.map((l) => {
          const [a, b] = l.segments.on;
          const last = (l.segments.off ?? l.segments.on)[1];
          const wind = l.segments.hover?.on ?? 0;
          if (!seed.current.has(l.id)) seed.current.set(l.id, l.rest);
          const first = seed.current.get(l.id) ?? 0;
          const pct = (f: number) => `${(f / last) * 100}%`;
          const end = () => {
            if (!scrubbing.current.delete(l.id)) return;
            l.release();
          };
          return (
            <li key={l.id} data-lane={l.id} data-last={last} className={styles.lane} style={{ '--pos': first / last } as CSSProperties}>
              <label htmlFor={`${uid}${l.id}`} className={styles.laneName}>{l.name}<span className={styles.srOnly}> timeline</span></label>
              <div className={styles.laneTrack}>
                <span className={styles.seg} data-kind="wind" style={{ left: pct(a), width: pct(wind) }} />
                <span className={styles.seg} data-kind="on" style={{ left: pct(a + wind), width: pct(b - a - wind) }} />
                {l.segments.off ? <span className={styles.seg} data-kind="off" style={{ left: pct(l.segments.off[0]), width: pct(l.segments.off[1] - l.segments.off[0]) }} /> : null}
                <span className={styles.head} aria-hidden="true" />
                <input
                  id={`${uid}${l.id}`}
                  className={styles.scrubber}
                  type="range"
                  min={0}
                  max={last}
                  step={1}
                  defaultValue={first}
                  aria-valuetext={valueText(first, last)}
                  onPointerDown={(ev) => {
                    scrubbing.current.add(l.id);
                    try { ev.currentTarget.setPointerCapture(ev.pointerId); } catch { /* not capturable */ }
                  }}
                  onKeyDown={(ev) => { if (STEP_KEYS.has(ev.key)) scrubbing.current.add(l.id); }}
                  onInput={(ev) => {
                    scrubbing.current.add(l.id);
                    const f = Number(ev.currentTarget.value);
                    show(l.id, f, false);
                    ev.currentTarget.setAttribute('aria-valuetext', valueText(f, last));
                    l.scrub(f);
                  }}
                  onPointerUp={end}
                  onPointerCancel={end}
                  onLostPointerCapture={end}
                  onBlur={end}
                />
              </div>
              <span data-frame="" className={styles.frameNo} aria-hidden="true">{two(first)}</span>
            </li>
          );
        })}
      </ol>
    </section>
  );
}
